fn jsonQuote(raw: Text) -> Text {
    let ms: MStream = mstream_new();
    mstream_write_byte(ms, ord("\""));
    loop ch in raw {
        let b: Int = ord(ch);
        if b == 34 {
            appendText(ms, "\\\"");
        } else if b == 92 {
            appendText(ms, "\\\\");
        } else if b == 10 {
            appendText(ms, "\\n");
        } else if b == 9 {
            appendText(ms, "\\t");
        } else {
            mstream_write_byte(ms, b);
        }
    }
    mstream_write_byte(ms, ord("\""));
    let quoted: Text = mstream_text(ms);
    mstream_free(ms);
    ret quoted;
}

