@pure
fn prefixTable(g: Int[][]) -> Int[][] {
    let cols: Int = length(g[0]);
    let zeros: Int[] = [];
    loop c in 0..cols + 1 {
        zeros = zeros + [0];
    }
    let pre: Int[][] = [zeros];
    loop r in 0..length(g) {
        let row: Int[] = [0];
        loop c in 0..cols {
            row = row + [g[r][c] + pre[r][c + 1] + row[c] - pre[r][c]];
        }
        pre = pre + [row];
    }
    ret pre;
}

