        let row: Bool[] = [];
        loop s in 0..limit + 1 {
            if can[i - 1][s] {
                row = row + [true];
            } else if s >= w {
                row = row + [can[i - 1][s - w]];
            } else {
                row = row + [false];
            }
        }
        can = can + [row];
    }

    fx {
        loop slot in slots {
            if can[n][slot] {
                let picked: Text = "";
                let left: Int = slot;
                loop i in n..0 step -1 {
                    if !can[i - 1][left] {
                        if picked == "" {
                            picked = names[i - 1];
                        } else {
                            picked = names[i - 1] + " + " + picked;
                        }
                        left = left - minutes[i - 1];
                    }
                }
                println(slot, " min: ", picked);
            } else {
                println(slot, " min: no exact fill");
            }
        }
    }
    ret;
}

