@pure
fn blur(img: Int[][]) -> Int[][] {
    let rows: Int = length(img);
    let out: Int[][] = [];
    loop r in 0..rows {
        let row: Int[] = [];
        loop c in 0..length(img[r]) {
            let sum: Int = 0;
            let count: Int = 0;
            loop y in r - 1..r + 2 {
                loop x in c - 1..c + 2 {
                    if y >= 0 && y < rows && x >= 0 && x < length(img[r]) {
                        sum = sum + img[y][x];
                        count = count + 1;
                    }
                }
            }
            row = row + [sum div count];
        }
        out = out + [row];
    }
    ret out;
}

