fn main() -> Void {
    let gold: Int[][] = [
        [1, 3, 1, 5, 2],
        [2, 2, 4, 1, 7],
        [5, 0, 2, 3, 1],
        [0, 6, 1, 2, 4]
    ];
    let rows: Int = length(gold);
    let cols: Int = length(gold[0]);
    let best: Int[][] = [];
    loop r in 0..rows {
        let row: Int[] = [0; cols];
        best = best + [row];
    }
    loop c in cols - 1..-1 step -1 {
        loop r in 0..rows {
            let ahead: Int = 0;
            if c < cols - 1 {
                loop y in max(r - 1, 0)..min(r + 2, rows) {
                    ahead = max(ahead, best[y][c + 1]);
                }
            }
            best[r][c] = gold[r][c] + ahead;
        }
    }
    let start: Int = 0;
    loop r in 1..rows {
        if best[r][0] > best[start][0] {
            start = r;
        }
    }
    let path: Int[] = [start];
    let r: Int = start;
    loop c in 0..cols - 1 {
        let next: Int = -1;
        loop y in max(r - 1, 0)..min(r + 2, rows) {
            if next < 0 || best[y][c + 1] > best[next][c + 1] {
                next = y;
            }
        }
        r = next;
        path = path + [r];
    }
    fx {
        println("most gold: ", best[start][0]);
        print("rows:");
        loop p in path {
            print(" ", p + 1);
        }
        println("");
    }
    ret;
}

@pure
fn insertionSorted(xs: Int[]) -> Int[] {
    loop i in 1..length(xs) {
        let v: Int = xs[i];
        let j: Int = i - 1;
        loop j >= 0 && xs[j] > v {
            xs[j + 1] = xs[j];
            j = j - 1;
        }
        xs[j + 1] = v;
    }
    ret xs;
}

