@pure
fn sortedCopy(xs: Int[]) -> Int[] {
    loop i in 1..length(xs) {
        let v: Int = xs[i];
        let j: Int = i - 1;
        loop j >= 0 && xs[j] > v {
            xs[j + 1] = xs[j];
            j = j - 1;
        }
        xs[j + 1] = v;
    }
    ret xs;
}

