fn toBase(n: Int, base: Int) -> Text {
    if n == 0 {
        ret "0";
    }
    let rest: Int = n;
    let out: Text = "";
    loop rest > 0 {
        out = DIGITS[rest % base] + out;
        rest = rest div base;
    }
    ret out;
}

