fn isqrt(n: Int) -> Int {
    let root: Int = 0;
    let stride: Int = 1000;
    loop stride > 0 {
        loop (root + stride) * (root + stride) <= n {
            root = root + stride;
        }
        stride = stride div 10;
    }
    ret root;
}

