        println("shift -21: ", shiftText(message, -21));
    }
    ret;
}

fn reverseDigits(n: Int) -> Int {
    let rest: Int = n;
    let out: Int = 0;
    loop rest > 0 {
        out = out * 10 + rest % 10;
        rest = rest div 10;
    }
    ret out;
}

