        raw = read_file("exhibits.json");
    }
    let doc: ToonDoc = toon_parse(raw);
    let root: ToonNode = toon_root(doc);
    let exhibits: ToonNode = toon_key(root, "exhibits");
    let oldest: ToonNode = toon_at(exhibits, 0);
    let newest: ToonNode = toon_at(exhibits, 0);
    let roomA: Int = 0;
    loop e in exhibits {
        let year: Int = toon_get_int_or(e, "year", 0);
        if year < toon_get_int_or(oldest, "year", 0) {
            oldest = e;
        }
        if year > toon_get_int_or(newest, "year", 0) {
            newest = e;
        }
        if toon_get_text_or(e, "room", "") == "A" {
            roomA = roomA + 1;
        }
    }
    fx {
        println(toon_get_text_or(root, "museum", "?"), ": ", toon_len(exhibits), " exhibits");
        println("oldest: ", toon_get_text_or(oldest, "title", "?"), " (", toon_get_int_or(oldest, "year", 0), ")");
        println("newest: ", toon_get_text_or(newest, "title", "?"), " (", toon_get_int_or(newest, "year", 0), ")");
        println("room A: ", roomA, " exhibits");
    }
    toon_close(doc);
    ret;
}

@pure
fn scaledLines(raw: Text, people: Int) -> Text[] {
    let doc: ToonDoc = toon_parse(raw);
    let root: ToonNode = toon_root(doc);
    let serves: Int = toon_get_int_or(root, "serves", 1);
    let out: Text[] = [toon_get_text_or(root, "recipe", "?") + " for " + int_to_text(people)];
    loop ing in toon_key(root, "ingredients") {
        let grams: Int = toon_get_int_or(ing, "grams", 0) * people div serves;
        out = out + [toon_get_text_or(ing, "name", "?") + " " + int_to_text(grams) + " g"];
    }
    toon_close(doc);
    ret out;
}

