        println("runner: ", runner);
        println("segments: ", length(secs));
        println("total: ", clockText(sum(secs)));
        println("fastest: ", fast, " s (segment ", index_of(secs, fast) + 1, ")");
        println("slowest: ", slow, " s (segment ", index_of(secs, slow) + 1, ")");
    }
    ret;
}

