@pure
fn flagsFor(stock: Int, expires: Text) -> Text[] {
    let flags: Text[] = [];
    if stock < 10 {
        flags = flags + ["reorder"];
    }
    if expires < "2027-01" {
        flags = flags + ["expiring"];
    }
    ret flags;
}

