@pure
fn padRight(t: Text, w: Int) -> Text {
    ret t + repeat(" ", w - string_len(t));
}

@pure
fn padLeft(t: Text, w: Int) -> Text {
    ret repeat(" ", w - string_len(t)) + t;
}

fn main() -> Void {
    let stations: Text[] = ["Harbor", "Ridge", "Valley", "Airfield"];
    let highs: Int[] = [18, 9, 23, -2];
    let table: MStream = mstream_new();
    mstream_write_text(table, padRight("STATION", 10) + padLeft("HIGH", 4) + "\n");
    mstream_write_text(table, repeat("-", 14) + "\n");
    loop i in 0..length(stations) {
        mstream_write_text(table, padRight(stations[i], 10) + padLeft(int_to_text(highs[i]), 4) + "\n");
    }
    let lines: Int = length(stations) + 2;
    let perLine: Int = mstream_length(table) div lines;
    fx {
        print(mstream_text(table));
        println("width check: ", perLine);
    }
    mstream_free(table);
    ret;
}

