            mstream_write_text(ms, ",");
        }
        mstream_write_text(ms, "{\"tank\":\"" + tanks[i] + "\",\"fish\":" + int_to_text(fish[i]) + "}");
    }
    mstream_write_text(ms, "]");
    let json: Text = mstream_text(ms);
    mstream_free(ms);

    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);
    let total: Int = 0;
    let best: Text = "";
    let bestCount: Int = -1;
    loop i in 0..toon_len(root) {
        let tank: ToonNode = toon_at(root, i);
        let n: Int = toon_get_int_or(tank, "fish", 0);
        total = total + n;
        if n > bestCount {
            bestCount = n;
            best = toon_get_text_or(tank, "tank", "");
        }
    }
    toon_close(doc);
    fx {
        println(json);
        println("total fish: ", total);
        println("busiest: ", best);
    }
    ret;
}

@pure
fn digitsOf(n: Int) -> Int[] {
    let rev: Int[] = [];
    let rest: Int = n;
    loop rest > 0 {
        rev = rev + [rest % 10];
        rest = rest div 10;
    }
    ret reversed(rev);
}

