    loop i in 0..length(songs) {
        let s: Song = songs[i];
        totalSec = totalSec + s.durationSec;
        if s.genre == "Pop" {
            popCount = popCount + 1;
            popTotal = popTotal + s.durationSec;
        }
        if s.genre == "Rock" {
            rockCount = rockCount + 1;
        }
        if s.genre == "Jazz" {
            jazzCount = jazzCount + 1;
        }
        if s.durationSec > 240 {
            over4 = over4 + 1;
        }
        if s.durationSec > longestDur {
            longestDur = s.durationSec;
            longestTitle = s.title;
        }
    }

    let avgPop: Real = 0.0;
    if popCount > 0 {
        avgPop = popTotal * 1.0 / popCount;
    }

    fx {
        println("Playlist length: ", totalSec);
        println("Pop songs: ", popCount);
