    let machineIdx: Int = 0;

    loop {
        if remaining < tokens[machineIdx] {
            break;
        }
        remaining = remaining - tokens[machineIdx];
        fx {
            println("Play ", playNum, " machine ", machineIdx + 1, " start ", currentTime, " tokens ", remaining);
        }
        currentTime = currentTime + duration[machineIdx];
        playNum = playNum + 1;
        machineIdx = machineIdx + 1;
        if machineIdx == 4 {
            machineIdx = 0;
        }
    }

    ret;
}

fn main() -> Void {
    let stationDist: Real[] = [5.0, 15.0, 25.0];
    let cups: Int[] = [40, 30, 25];
    let speeds: Real[] = [0.25, 0.20, 0.30, 0.22];
    let needs: Int[][] = [
        [1, 2, 1],
        [2, 1, 2],
        [1, 1, 1],
        [2, 2, 1]
    ];

    let nRunners: Int = 4;
    let nStations: Int = 3;

    let times: Real[][] = [];
    loop r in 0..nRunners {
        let row: Real[] = [];
        loop s in 0..nStations {
            row = row + [stationDist[s] / speeds[r]];
        }
        times = times + [row];
    }

    let order: Int[] = [0, 1, 2, 3];
    loop i in 1..nRunners {
        let v: Int = order[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if order[j] <= v {
                break;
            }
            order[j + 1] = order[j];
            j = j - 1;
        }
        order[j + 1] = v;
    }

    let events: Int[] = [];
    loop i in 0..nRunners {
        loop s in 0..nStations {
            events = events + [i * nStations + s];
        }
    }

    loop i in 1..length(events) {
        let v: Int = events[i];
        let j: Int = i - 1;
        loop j >= 0 {
            let evA: Int = events[j];
            let evB: Int = v;
            let rA: Int = evA div nStations;
            let sA: Int = evA % nStations;
            let rB: Int = evB div nStations;
            let sB: Int = evB % nStations;
            let tA: Real = times[rA][sA];
            let tB: Real = times[rB][sB];
            if tA < tB {
                break;
            }
            if tA == tB && rA <= rB {
                break;
            }
            events[j + 1] = events[j];
            j = j - 1;
        }
        events[j + 1] = v;
    }

    loop i in 0..length(events) {
        let ev: Int = events[i];
        let r: Int = ev div nStations;
        let s: Int = ev % nStations;
        let need: Int = needs[r][s];
        let take: Int = min(need, cups[s]);
        cups[s] = cups[s] - take;
    }

    fx {
        println("Station 1 remaining ", cups[0]);
        println("Station 2 remaining ", cups[1]);
        println("Station 3 remaining ", cups[2]);
    }
    ret;
}

