            if grid[r][c] == 1 {
                obstacleCount = obstacleCount + 1;
                rowObs = rowObs + 1;
                colBlockages[c] = colBlockages[c] + 1;
            } else {
                freeCount = freeCount + 1;
            }
        }
        rowBlockages = rowBlockages + [rowObs];
        if rowObs == 0 {
            clearRows = clearRows + [r + 1];
        }
    }

    fx {
        println("Grid Obstacles");
        loop r in 0..rows {
            loop c in 0..cols {
                if c > 0 {
                    print(" ");
                }
                print(grid[r][c]);
            }
            println("");
        }
        println("Obstacle Count: ", obstacleCount);
        println("Free Count: ", freeCount);
        print("Row Blockages: ");
        loop i in 0..length(rowBlockages) {
            if i > 0 {
                print(" ");
            }
            print(rowBlockages[i]);
        }
        println("");
        print("Col Blockages: ");
        loop i in 0..length(colBlockages) {
            if i > 0 {
                print(" ");
            }
            print(colBlockages[i]);
        }
        println("");
        if length(clearRows) == 0 {
            println("Clear Rows: none");
        } else {
            print("Clear Rows: ");
            loop i in 0..length(clearRows) {
                if i > 0 {
                    print(" ");
                }
                print(clearRows[i]);
            }
            println("");
        }
    }
    ret;
}

fn main() -> Void {
    let b11: Real[][] = [[2.5, 3.0, 1.5], [2.0, 3.5, 2.5]];
    let b12: Real[][] = [[4.0, 3.5, 4.5], [3.0, 4.0, 3.5]];
    let b21: Real[][] = [[1.0, 1.5, 2.0], [1.5, 2.5, 1.0]];
    let b22: Real[][] = [[3.5, 4.0, 3.0], [4.5, 3.0, 4.0]];

    let beds: Real[][][] = [b11, b12, b21, b22];

    let total: Real = 0.0;
    let maxFlow: Real = 0.0;
    let minFlow: Real = 999999.0;

    let bedSums: Real[] = [0.0, 0.0, 0.0, 0.0];

    loop bi in 0..length(beds) {
        let bed: Real[][] = beds[bi];
        loop r in 0..length(bed) {
            loop c in 0..length(bed[r]) {
                let v: Real = bed[r][c];
                bedSums[bi] = bedSums[bi] + v;
                total = total + v;
                if v > maxFlow {
                    maxFlow = v;
                }
                if v < minFlow {
                    minFlow = v;
                }
            }
        }
    }

    fx {
        println("Irrigation Flow");
        loop bi in 0..length(beds) {
            let row: Int = bi div 2 + 1;
            let col: Int = bi % 2 + 1;
            let avg: Real = bedSums[bi] / 6.0;
            println("Bed (", int_to_text(row), ",", int_to_text(col), "): ", formatfloat(avg, 2));
        }
        println("Total Flow: ", formatfloat(total, 2));
        println("Max Flow: ", formatfloat(maxFlow, 2));
        println("Min Flow: ", formatfloat(minFlow, 2));
    }
    ret;
}

