    let total: Int = 0;

    loop r in 0..rows {
        let row: Int[] = [];
        loop c in 0..cols {
            let val: Int = grid[r][c];
            let sum: Int = 0;
            if r > 0 {
                sum = sum + grid[r - 1][c];
            }
            if r < rows - 1 {
                sum = sum + grid[r + 1][c];
            }
            if c > 0 {
                sum = sum + grid[r][c - 1];
            }
            if c < cols - 1 {
                sum = sum + grid[r][c + 1];
            }
            if val >= 20 && sum >= 50 {
                row = row + [1];
                total = total + 1;
            } else {
                row = row + [0];
            }
        }
        crowded = crowded + [row];
    }

    fx {
        loop r in 0..rows {
            loop c in 0..cols {
                if c > 0 {
                    print(" ");
                }
                print(crowded[r][c]);
            }
            println("");
        }
        println("CROWDED ", total);
    }
    ret;
}

fn main() -> Void {
    let carbons: Int[] = [400, 350, 600, 250, 450, 700, 180, 520];
    let nitrogens: Int[] = [20, 15, 40, 10, 30, 25, 12, 35];
    let n: Int = length(carbons);

    let balanced: Int = 0;
    let highest: Real = 0.0;
    let lowest: Real = 0.0;
    let idealIdx: Int = 0;
    let idealDist: Real = 0.0;

    loop i in 0..n {
        let ratio: Real = carbons[i] * 1.0 / nitrogens[i];
        if ratio >= 20.0 && ratio <= 30.0 {
            balanced = balanced + 1;
        }
        if i == 0 {
            highest = ratio;
            lowest = ratio;
            idealIdx = 0;
            idealDist = abs(ratio - 25.0);
        } else {
            if ratio > highest {
                highest = ratio;
            }
            if ratio < lowest {
                lowest = ratio;
            }
            let d: Real = abs(ratio - 25.0);
            if d < idealDist {
                idealDist = d;
                idealIdx = i;
            }
        }
    }

    fx {
        println("Batches: ", n);
        println("Balanced: ", balanced);
        println("Highest Ratio: ", formatfloat(highest, 2));
        println("Lowest Ratio: ", formatfloat(lowest, 2));
        println("Ideal Batch: ", idealIdx + 1);
    }
    ret;
}

