        sortedR = sortedR[0..j] + [r] + sortedR[j..];
    }

    loop i in 0..n {
        fx {
            println(sortedV[i], " ", formatfloat(sortedR[i], 1), "%");
        }
    }
    ret;
}

fn main() -> Void {
    let names: Text[] = ["Pushup", "Situp", "Squat", "Lunge", "PlankSec", "Burpee"];
    let reps: Int[] = [32, 45, 32, 18, 45, 12];
    let n: Int = length(reps);

    // Collect distinct rep values
    let distinct: Int[] = [];
    loop i in 0..n {
        let found: Bool = false;
        loop j in 0..length(distinct) {
            if distinct[j] == reps[i] {
                found = true;
            }
        }
        if !found {
            distinct = distinct + [reps[i]];
        }
    }

    // Sort distinct in descending order (insertion sort)
    let d: Int = length(distinct);
    loop i in 1..d {
        let v: Int = distinct[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if distinct[j] >= v {
                break;
            }
            distinct[j + 1] = distinct[j];
            j = j - 1;
        }
        distinct[j + 1] = v;
    }

    // Assign ranks: for each exercise, find its rep's position in sorted distinct
    loop i in 0..n {
        let rank: Int = 1;
        loop k in 0..d {
            if distinct[k] == reps[i] {
                rank = k + 1;
            }
        }
        fx {
            println(names[i], " = ", rank);
        }
    }
    ret;
}

fn main() -> Void {
    let titles: Text[] = ["Driftwood", "Iron Sky", "Quiet Harbor", "Red Mesa", "Silver Fern", "Tide Pool"];
    let fines: Int[] = [5, 12, 3, 12, 7, 3];
    let n: Int = length(titles);

    let sortedTitles: Text[] = [];
    let sortedFines: Int[] = [];

    loop i in 0..n {
        let t: Text = titles[i];
        let f: Int = fines[i];
        let j: Int = length(sortedTitles);
        loop j >= 0 {
            if j == 0 {
                break;
            }
            if sortedFines[j - 1] <= f {
                break;
            }
            j = j - 1;
        }
        let before: Text[] = sortedTitles[0..j];
        let after: Text[] = sortedTitles[j..];
        sortedTitles = before + [t] + after;
        let beforeF: Int[] = sortedFines[0..j];
        let afterF: Int[] = sortedFines[j..];
        sortedFines = beforeF + [f] + afterF;
    }

    loop i in 0..n {
        fx {
            println(sortedTitles[i], " $", sortedFines[i]);
        }
    }
    ret;
}

fn main() -> Void {
    let names: Text[] = ["B1", "B2", "B3", "B4", "B5", "B6"];
    let temps: Real[] = [21.4, 19.8, 23.6, 21.4, 18.2, 20.5];
    let n: Int = length(names);

    let order: Int[] = [];
    loop i in 0..n {
        order = order + [i];
    }

    loop i in 1..n {
        let key: Int = order[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if temps[order[j]] >= temps[key] {
                break;
            }
            order[j + 1] = order[j];
            j = j - 1;
        }
        order[j + 1] = key;
    }

    fx {
        loop i in 0..n {
            let idx: Int = order[i];
            println(names[idx], " ", formatfloat(temps[idx], 1));
        }
    }
    ret;
}

