fn main() -> Void {
    let titles: Text[] = ["Ants", "Birds", "Cacti", "Dunes", "Eagles", "Ferns"];
    let dewey: Int[] = [595, 598, 580, 551, 598, 580];
    let n: Int = length(titles);

    let sortedTitles: Text[] = [];
    let sortedDewey: Int[] = [];

    loop i in 0..n {
        let t: Text = titles[i];
        let d: Int = dewey[i];
        let j: Int = length(sortedTitles);
        while j > 0 && sortedDewey[j - 1] > d {
            j = j - 1;
        }
        let newTitles: Text[] = [];
        let newDewey: Int[] = [];
        loop k in 0..j {
            newTitles = newTitles + [sortedTitles[k]];
            newDewey = newDewey + [sortedDewey[k]];
        }
        newTitles = newTitles + [t];
        newDewey = newDewey + [d];
        loop k in j..length(sortedTitles) {
            newTitles = newTitles + [sortedTitles[k]];
            newDewey = newDewey + [sortedDewey[k]];
        }
        sortedTitles = newTitles;
        sortedDewey = newDewey;
    }

    fx {
        loop i in 0..n {
            println(sortedTitles[i], " ", sortedDewey[i]);
        }
    }
    ret;
}

@pure
fn countDistinctLess(paces: Real[], target: Real) -> Int {
    let count: Int = 0;
    loop i in 0..length(paces) {
        if paces[i] < target {
            // Check if this pace is already counted (i.e., appears earlier)
            let already: Bool = false;
            loop j in 0..i {
                if paces[j] == paces[i] {
                    already = true;
                    break;
                }
            }
            if !already {
                count = count + 1;
            }
        }
    }
    ret count;
}

fn main() -> Void {
    let names: Text[] = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    let paces: Real[] = [5.4, 4.9, 6.1, 5.4, 4.9, 5.8];
    let n: Int = length(paces);
    let ranks: Int[] = [];
    loop i in 0..n {
        let r: Int = countDistinctLess(paces, paces[i]) + 1;
        ranks = ranks + [r];
    }
    fx {
        loop i in 0..n {
            println(names[i], " = ", ranks[i]);
        }
    }
    ret;
}

fn fmtTime(m: Int) -> Text {
    let h: Int = m div 60;
    let mm: Int = m % 60;
    let hs: Text = int_to_text(h);
    let ms: Text = int_to_text(mm);
    let hp: Text = "";
    if string_len(hs) == 1 {
        hp = "0" + hs;
    } else {
        hp = hs;
    }
    let mp: Text = "";
    if string_len(ms) == 1 {
        mp = "0" + ms;
    } else {
        mp = ms;
    }
    ret hp + ":" + mp;
}

