    ];
    let m14: Int[][] = [
        [2, 4, 6, 3, 5],
        [8, 3, 2, 7, 1],
        [5, 6, 9, 4, 2],
        [1, 7, 5, 8, 3],
        [6, 1, 4, 2, 9]
    ];

    let peak10: Int = 0;
