fn main() -> Void {
    let power: Int[][] = [
        [100, 120, 90, 110, 130],
        [140, 150, 160, 100, 95],
        [85, 105, 115, 125, 135],
        [90, 145, 155, 165, 100],
        [110, 120, 130, 140, 150]
    ];

    let rows: Int = 5;
    let cols: Int = 5;
    let shadowed: Int = 0;
    let strong: Int = 0;
    let hidden: Int = 0;
    let colsum: Int[] = [0, 0, 0, 0, 0];

    loop r in 0..rows {
        loop c in 0..cols {
            let p: Int = power[r][c];
            colsum[c] = colsum[c] + p;

            if p >= 140 {
                strong = strong + 1;
            }

            let isShadowed: Bool = false;
            if r > 0 && power[r - 1][c] < 100 {
                isShadowed = true;
            }
            if r < rows - 1 && power[r + 1][c] < 100 {
                isShadowed = true;
            }
            if c > 0 && power[r][c - 1] < 100 {
                isShadowed = true;
            }
            if c < cols - 1 && power[r][c + 1] < 100 {
                isShadowed = true;
            }

            if isShadowed {
                shadowed = shadowed + 1;
                if p < 100 {
                    hidden = hidden + 1;
                }
            }
        }
    }

    let bestCol: Int = 0;
    let bestSum: Int = colsum[0];
    loop c in 1..cols {
        if colsum[c] > bestSum {
            bestSum = colsum[c];
            bestCol = c;
        }
    }

    fx {
        println("SHADOWED ", shadowed);
        println("STRONG ", strong);
        println("HIDDEN ", hidden);
        println("COLSUM ", colsum[0], " ", colsum[1], " ", colsum[2], " ", colsum[3], " ", colsum[4]);
        println("BESTCOL ", bestCol, " ", bestSum);
    }
    ret;
}

fn minCoins(amount: Int) -> Int {
    let coins: Int[] = [50, 25, 10, 5, 1];
    let count: Int = 0;
    loop d in coins {
        let q: Int = amount div d;
        count = count + q;
        amount = amount % d;
    }
    ret count;
}

