fn main() -> Void {
    let names: Text[] = ["Tom", "Sara", "Mike", "Lisa", "John", "Amy", "Ben"];
    let splits: Int[] = [4800, 5100, 5500, 4900, 6200, 5250, 6800];
    let n: Int = length(names);
    let order: Int[] = [];
    loop i in 0..n {
        order = order + [i];
    }
    loop i in 1..n {
        let v: Int = order[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if splits[order[j]] <= splits[v] {
                break;
            }
            order[j + 1] = order[j];
            j = j - 1;
        }
        order[j + 1] = v;
    }
    loop i in 0..n {
        fx {
            println(i + 1, ": ", names[order[i]]);
        }
    }
    ret;
}

@pure
fn shippingCost(weight: Int) -> Real {
    if weight <= 5 {
        ret weight * 4.0;
    }
    ret 5.0 * 4.0 + (weight - 5) * 2.5;
}

