fn main() -> Void {
    let ring: Int[] = [1, 0, 1, 1, 0, 1];

    // 1. ROTATE CLOCKWISE: shift right, slot 5 -> slot 0
    let tmp: Int = ring[5];
    loop i in 5..0 step -1 {
        ring[i] = ring[i - 1];
    }
    ring[0] = tmp;

    // 2. TOGGLE slot 2
    ring[2] = 1 - ring[2];

    // 3. ROTATE CLOCKWISE
    let tmp2: Int = ring[5];
    loop i in 5..0 step -1 {
        ring[i] = ring[i - 1];
    }
    ring[0] = tmp2;

    // 4. TOGGLE slot 0
    ring[0] = 1 - ring[0];

    // 5. ROTATE COUNTERCLOCKWISE: shift left, slot 0 -> slot 5
    let tmp3: Int = ring[0];
    loop i in 0..5 {
        ring[i] = ring[i + 1];
    }
    ring[5] = tmp3;

    // 6. TOGGLE slot 4
    ring[4] = 1 - ring[4];

    fx {
        loop i in 0..6 {
            println("Slot ", i, ": ", ring[i]);
        }
    }
    ret;
}

fn main() -> Void {
    let changes: Int[] = [3, 4, -2, 5, -1, 6, -3, 2, -7, 4, -5, 1];
    let floor: Int = 0;
    let highest: Int = 0;
    let clamped: Int = 0;

    loop i in 0..length(changes) {
        let raw: Int = floor + changes[i];
        if raw < 0 || raw > 10 {
            clamped = clamped + 1;
        }
        floor = clamp(raw, 0, 10);
        if floor > highest {
            highest = floor;
        }
    }

    fx {
        println("Final floor: ", floor);
        println("Highest floor reached: ", highest);
        println("Number of times clamped: ", clamped);
    }
    ret;
}

