fn main() -> Void {
    let colors: Text[] = ["C", "K", "M", "Y"];
    let count: Int = 0;

    loop a in 0..4 {
        loop b in 0..4 {
            if colors[b] == colors[a] {
                continue;
            }
            loop c in 0..4 {
                if colors[c] == colors[b] {
                    continue;
                }
                let seq: Text = colors[a] + colors[b] + colors[c];
                let kCount: Int = 0;
                loop ch in seq {
                    if ch == "K" {
                        kCount = kCount + 1;
                    }
                }
                if kCount > 1 {
                    continue;
                }
                let hasY: Bool = false;
                let hasC: Bool = false;
                let cBeforeY: Bool = true;
                loop i in 0..3 {
                    let ch: Text = seq[i];
                    if ch == "Y" {
                        hasY = true;
                        if !hasC {
                            cBeforeY = false;
                        }
                    }
                    if ch == "C" {
                        hasC = true;
                    }
                }
                if hasY && !cBeforeY {
                    continue;
                }
                fx {
                    println(seq);
                }
                count = count + 1;
            }
        }
    }

    fx {
        println("");
        println("TOTAL JOBS: ", count);
    }
    ret;
}

