// Lighthouse Day Signals
// 5 days, each C or F
// Exactly 3 C and 2 F
// Two F days never adjacent
// Day 1 is C

fn main() -> Void {
    let count: Int = 0;
    // Day 1 is always C, so we only iterate days 2-5
    // Each day is 0 (C) or 1 (F)
    loop d2 in 0..2 {
        loop d3 in 0..2 {
            loop d4 in 0..2 {
                loop d5 in 0..2 {
                    // Day 1 = C (0), so total F count = d2 + d3 + d4 + d5
                    let foggy: Int = d2 + d3 + d4 + d5;
                    if foggy == 2 {
                        // Check adjacency: no two consecutive F days
                        // Days: 1(C), 2(d2), 3(d3), 4(d4), 5(d5)
                        let adj: Bool = false;
                        if d2 == 1 && d3 == 1 {
                            adj = true;
                        }
                        if d3 == 1 && d4 == 1 {
                            adj = true;
                        }
                        if d4 == 1 && d5 == 1 {
                            adj = true;
                        }
                        if !adj {
                            let s: Text = "C";
                            if d2 == 1 {
                                s = s + "F";
                            } else {
                                s = s + "C";
                            }
                            if d3 == 1 {
                                s = s + "F";
                            } else {
                                s = s + "C";
                            }
                            if d4 == 1 {
                                s = s + "F";
                            } else {
                                s = s + "C";
                            }
                            if d5 == 1 {
                                s = s + "F";
                            } else {
                                s = s + "C";
                            }
                            fx {
                                println(s);
                            }
                            count = count + 1;
                        }
                    }
                }
            }
        }
    }
    fx {
        println("");
        println("RECORDS: ", count);
    }
    ret;
}

fn main() -> Void {
    let grid: Real[][] = [
        [120.0, 130.0, 140.0],
        [150.0, 160.0, 170.0],
        [180.0, 190.0, 200.0]
    ];

    let rows: Int = 3;
    let cols: Int = 3;

    loop r in 0..rows {
        loop c in 0..cols {
            let sum: Real = grid[r][c];
            let count: Int = 1;

            if r > 0 {
                sum = sum + grid[r - 1][c];
                count = count + 1;
            }
            if r < rows - 1 {
                sum = sum + grid[r + 1][c];
                count = count + 1;
            }
            if c > 0 {
                sum = sum + grid[r][c - 1];
                count = count + 1;
            }
            if c < cols - 1 {
                sum = sum + grid[r][c + 1];
                count = count + 1;
            }

            let avg: Real = sum / count;
            let val: Text = formatfloat(avg, 2);

            if c == 0 {
                fx { print(val); }
            } else {
                fx { print(" ", val); }
            }
        }
        fx { println(""); }
    }

    ret;
}

