from collections import deque

dist = {}
count = {}
dist[start] = 1
count[start] = 1
q = deque([start])

while q:
    x, y = q.popleft()
    d = dist[(x,y)]
    for nx, ny in [(x+1, y), (x, y+1)]:
        if valid((nx, ny)):
            nd = d + 1
            if (nx, ny) not in dist:
                dist[(nx, ny)] = nd
                count[(nx, ny)] = count[(x, y)]
                q.append((nx, ny))
            elif dist[(nx, ny)] == nd:
                count[(nx, ny)] += count[(x, y)]

