fn isGolden(code: Int) -> Bool {
    if code % 3 != 0 {
        ret false;
    }
    let ds: Int = digitSum(code);
    if ds <= 10 {
        ret false;
    }
    if code % ds != 0 {
        ret false;
    }
    ret true;
}

