@pure
fn to_base4(n: Int) -> Text {
    if n == 0 {
        ret "0";
    }
    let digits: Int[] = [];
    let v: Int = n;
    loop {
        let d: Int = v % 4;
        digits = digits + [d];
        v = v div 4;
        if v == 0 {
            break;
        }
    }
    let len: Int = length(digits);
    let result: Text = "";
    loop i in 0..len {
        result = result + int_to_text(digits[len - 1 - i]);
    }
    ret result;
}

