fn titleCase(s: Text) -> Text {
    let words: Text[] = split(s, " ");
    let out: Text[] = [];
    loop w in words {
        let n: Int = string_len(w);
        if n == 0 {
            out = out + [""];
        } else {
            let first: Text = upper(w[0..1]);
            let rest: Text = lower(w[1..]);
            out = out + [first + rest];
        }
    }
    ret join(out, " ");
}

