type Song {
    title: Text = "";
    plays: Int = 0;
    idx: Int = 0;
}

fn main() -> Void {
    let songs: Song[] = [
        new Song { title: "Sunset Drive", plays: 45, idx: 0 },
        new Song { title: "Ocean Breeze", plays: 78, idx: 1 },
        new Song { title: "Mountain Trail", plays: 45, idx: 2 },
        new Song { title: "City Lights", plays: 92, idx: 3 },
        new Song { title: "Desert Wind", plays: 31, idx: 4 },
        new Song { title: "River Song", plays: 78, idx: 5 }
    ];

    let n: Int = length(songs);
    let ranked: Song[] = [];
    let remaining: Song[] = songs;

    loop r in 0..n {
        let best: Int = -1;
        loop i in 0..length(remaining) {
            if best == -1 {
                best = i;
            } else {
                if remaining[i].plays > remaining[best].plays {
                    best = i;
                } else if remaining[i].plays == remaining[best].plays && remaining[i].idx < remaining[best].idx {
                    best = i;
                }
            }
        }
        ranked = ranked + [remaining[best]];
        let next: Song[] = [];
        loop i in 0..length(remaining) {
            if i != best {
                next = next + [remaining[i]];
            }
        }
        remaining = next;
    }

    loop r in 0..n {
        let s: Song = ranked[r];
        fx {
            println("Rank ", r + 1, ": \"", s.title, "\" (", s.plays, " plays)");
        }
    }

    ret;
}

