                if si < ej && sj < ei {
                    if boards[i] == 1 {
                        b1 = b1 + 1;
                    }
                    if boards[i] == 2 {
                        b2 = b2 + 1;
                    }
                    if boards[i] == 3 {
                        b3 = b3 + 1;
                    }
                    if boards[i] == 4 {
                        b4 = b4 + 1;
                    }
                }
            }
        }
    }

    let busy: Int = 0;
    loop minute in 0..100 {
