fn main() -> Void {
    let orderNums: Int[] = [1, 2, 3, 4, 5, 6];
    let arrivals: Int[] = [0, 2, 4, 10, 12, 15];
    let preps: Int[] = [5, 8, 3, 6, 4, 7];

    let stationEnd: Int[] = [0, 0];
    let stationUsed: Int[] = [0, 0, 0, 0, 0, 0];
    let startMins: Int[] = [0, 0, 0, 0, 0, 0];
    let endMins: Int[] = [0, 0, 0, 0, 0, 0];

    loop i in 0..6 {
        let arr: Int = arrivals[i];
        let prep: Int = preps[i];
        let s1: Int = stationEnd[0];
        let s2: Int = stationEnd[1];
        let chosen: Int = 0;
        let start: Int = 0;

        if s1 <= arr {
            chosen = 0;
            start = arr;
        } else if s2 <= arr {
            chosen = 1;
            start = arr;
        } else if s1 <= s2 {
            chosen = 0;
            start = s1;
        } else {
            chosen = 1;
            start = s2;
        }

        let end: Int = start + prep;
        stationEnd[chosen] = end;
        stationUsed[i] = chosen + 1;
        startMins[i] = start;
        endMins[i] = end;
    }

    fx {
        loop i in 0..6 {
            println("Order ", orderNums[i], ": station ", stationUsed[i], ", start minute ", startMins[i], ", end minute ", endMins[i]);
