fn main() -> Void {
    let total: Int = 0;
    let wSlot1: Int = 0;
    let xLeftY: Int = 0;
    let zNotEnd: Int = 0;
    let wxAdj: Int = 0;
    let noMatch: Int = 0;

    loop a in 0..4 {
        loop b in 0..4 {
            if b == a { continue; }
            loop c in 0..4 {
                if c == a or c == b { continue; }
                loop d in 0..4 {
                    if d == a or d == b or d == c { continue; }

                    total = total + 1;

                    if a == 0 {
                        wSlot1 = wSlot1 + 1;
                    }

                    if b < c {
                        xLeftY = xLeftY + 1;
                    }

                    if d != 0 and d != 3 {
                        zNotEnd = zNotEnd + 1;
                    }

                    let diff: Int = a - b;
                    if diff < 0 { diff = -diff; }
                    if diff == 1 {
                        wxAdj = wxAdj + 1;
                    }

                    let ok: Bool = true;
                    if a == 0 { ok = false; }
                    if b == 1 { ok = false; }
                    if c == 2 { ok = false; }
                    if d == 3 { ok = false; }
                    if ok {
                        noMatch = noMatch + 1;
                    }
                }
            }
        }
    }

    fx {
        println("Total assignments: ", total);
        println("Assignments with W in slot 1: ", wSlot1);
        println("Assignments where X is to the left of Y: ", xLeftY);
        println("Assignments where Z is not at either end: ", zNotEnd);
        println("Assignments where W and X are adjacent: ", wxAdj);
        println("Assignments where no sensor is in its matching-numbered slot: ", noMatch);
    }
    ret;
}

fn main() -> Void {
    let total: Int = 0;
    let allEqual: Int = 0;
    let exactlyOneSix: Int = 0;
    let nonDecreasing: Int = 0;
    let sum14: Int = 0;
    let noConsecutive: Int = 0;
    let found: Bool = false;
    let bestA: Int = 0;
    let bestB: Int = 0;
    let bestC: Int = 0;
    let bestD: Int = 0;

    loop a in 1..7 {
        loop b in 1..7 {
            loop c in 1..7 {
                loop d in 1..7 {
                    total = total + 1;

                    if a == b && b == c && c == d {
                        allEqual = allEqual + 1;
                    }

                    let sixCount: Int = 0;
                    if a == 6 { sixCount = sixCount + 1; }
                    if b == 6 { sixCount = sixCount + 1; }
                    if c == 6 { sixCount = sixCount + 1; }
                    if d == 6 { sixCount = sixCount + 1; }
                    if sixCount == 1 {
                        exactlyOneSix = exactlyOneSix + 1;
                    }

                    if a <= b && b <= c && c <= d {
                        nonDecreasing = nonDecreasing + 1;
                    }

                    let s: Int = a + b + c + d;
                    if s == 14 {
                        sum14 = sum14 + 1;
                        if !found {
                            found = true;
                            bestA = a;
                            bestB = b;
                            bestC = c;
                            bestD = d;
                        }
                    }

                    if a != b && b != c && c != d {
                        noConsecutive = noConsecutive + 1;
                    }
                }
            }
        }
    }

    fx {
        println("Total sequences: ", total);
        println("Sequences with all four rolls equal: ", allEqual);
        println("Sequences with exactly one 6: ", exactlyOneSix);
        println("Sequences in non-decreasing order: ", nonDecreasing);
        println("Sequences where the sum is 14: ", sum14);
        println("Sequences where no two consecutive rolls are equal: ", noConsecutive);
        if found {
            println("Smallest sequence with sum 14: ", bestA, " ", bestB, " ", bestC, " ", bestD);
