    let root: ToonNode = toon_root(doc);
    let orders: ToonNode = toon_key(root, "orders");
    let n: Int = toon_len(orders);

    let delivered: Int = 0;
    let pendingTotal: Real = 0.0;
    let topPrice: Real = 0.0;
    let topRoom: Int = 0;
    let topItem: Text = "";

    let rooms: Int[] = [];
    let roomCounts: Int[] = [];
    let roomTotals: Real[] = [];

    loop i in 0..n {
        let row: ToonNode = toon_at(orders, i);
        let room: Int = toon_get_int_or(row, "room", 0);
        let item: Text = toon_get_text_or(row, "item", "");
        let price: Real = toon_get_real_or(row, "price", 0.0);
        let isDelivered: Bool = toon_get_bool_or(row, "delivered", false);

        if isDelivered {
            delivered = delivered + 1;
        } else {
            pendingTotal = pendingTotal + price;
        }

        if i == 0 || price > topPrice {
            topPrice = price;
            topRoom = room;
            topItem = item;
        }

        let found: Bool = false;
        loop j in 0..length(rooms) {
            if rooms[j] == room {
                found = true;
                roomCounts[j] = roomCounts[j] + 1;
                roomTotals[j] = roomTotals[j] + price;
                break;
            }
        }
        if !found {
            rooms = rooms + [room];
            roomCounts = roomCounts + [1];
            roomTotals = roomTotals + [price];
        }
    }

    let sortedRooms: Int[] = sorted(rooms);
    let sortedCounts: Int[] = [];
    let sortedTotals: Real[] = [];
    loop i in 0..length(sortedRooms) {
        let r: Int = sortedRooms[i];
        loop j in 0..length(rooms) {
            if rooms[j] == r {
                sortedCounts = sortedCounts + [roomCounts[j]];
                sortedTotals = sortedTotals + [roomTotals[j]];
                break;
            }
        }
    }

    fx {
        println("Orders: ", n);
        println("Delivered: ", delivered);
