    let root: ToonNode = toon_root(doc);
    let stock: ToonNode = toon_key(root, "stock");
    let n: Int = toon_len(stock);

    let totalUnits: Int = 0;
    let totalValue: Real = 0.0;
    let topPrice: Real = -1.0;
    let topCat: Text = "";
    let topModel: Text = "";
    let botPrice: Real = 999999.0;
    let botCat: Text = "";
    let botModel: Text = "";

    let cats: Text[] = [];
    let catUnits: Int[] = [];
    let catValues: Real[] = [];

    loop i in 0..n {
        let row: ToonNode = toon_at(stock, i);
        let cat: Text = toon_get_text_or(row, "category", "");
        let model: Text = toon_get_text_or(row, "model", "");
        let price: Real = toon_get_real_or(row, "price", 0.0);
        let count: Int = toon_get_int_or(row, "count", 0);
        let countR: Real = real(count);

        totalUnits = totalUnits + count;
        totalValue = totalValue + price * countR;

        if price > topPrice {
            topPrice = price;
            topCat = cat;
            topModel = model;
        }
        if price < botPrice {
            botPrice = price;
            botCat = cat;
            botModel = model;
        }

        let found: Bool = false;
        loop j in 0..length(cats) {
            if cats[j] == cat {
                found = true;
                catUnits[j] = catUnits[j] + count;
                catValues[j] = catValues[j] + price * countR;
                break;
            }
        }
        if !found {
            cats = cats + [cat];
            catUnits = catUnits + [count];
            catValues = catValues + [price * countR];
        }
    }

    fx {
        println("Total units: ", totalUnits);
        println("Stock value: $", formatfloat(totalValue, 2));
        loop j in 0..length(cats) {
            println(cats[j], ": units=", catUnits[j], " value=$", formatfloat(catValues[j], 2));
        }
        println("Top: ", topCat, " ", topModel, " $", formatfloat(topPrice, 2));
        println("Bottom: ", botCat, " ", botModel, " $", formatfloat(botPrice, 2));
