fn main() -> Void {
    let lines: Text[];
    fx { lines = read_lines("seedlings.txt"); }

    let validCount: Int = 0;
    let invalidCount: Int = 0;
    let totalTrays: Int = 0;
    let healthSum: Real = 0.0;
    let dryCount: Int = 0;
    let lowestHealth: Real = 0.0;
    let lowestPlant: Text = "NONE";
    let hasLowest: Bool = false;

    loop line in lines {
        let trimmed: Text = trim(line);
        if trimmed == "" {
            continue;
        }
        let parts: Text[] = split(trimmed, " ");
        if length(parts) != 4 {
            invalidCount = invalidCount + 1;
            continue;
        }
        let name: Text = parts[0];
        let trayText: Text = parts[1];
        let healthText: Text = parts[2];
        let status: Text = parts[3];

        let (trayVal, trayOk) = try_parse_int(trayText);
        let (healthVal, healthOk) = try_parse_real(healthText);

        if !trayOk || !healthOk {
            invalidCount = invalidCount + 1;
            continue;
        }

        if trayVal <= 0 || healthVal < 0.0 || healthVal > 100.0 {
            invalidCount = invalidCount + 1;
            continue;
        }

        validCount = validCount + 1;
        totalTrays = totalTrays + trayVal;
        healthSum = healthSum + healthVal;
        if status == "DRY" {
            dryCount = dryCount + 1;
        }
        if !hasLowest || healthVal < lowestHealth {
            lowestHealth = healthVal;
            lowestPlant = name;
            hasLowest = true;
        }
    }

    let avgHealth: Real = 0.0;
    if validCount > 0 {
        avgHealth = healthSum / (validCount * 1.0);
    }

    fx {
        println("Valid records: ", validCount);
        println("Invalid records: ", invalidCount);
