fn main() -> Void {
    let lines: Text[];
    fx { lines = read_lines("planting.txt"); }

    let validCount: Int = 0;
    let invalidCount: Int = 0;
    let totalPlants: Int = 0;
    let springCount: Int = 0;
    let summerCount: Int = 0;
    let earliest: Int = 0;
    let speciesList: Text[] = [];
    let speciesCounts: Int[] = [];

    loop line in lines {
        let trimmed: Text = trim(line);
        if trimmed == "" {
            continue;
        }
        let parts: Text[] = split(trimmed, " ");
        if length(parts) != 4 {
            invalidCount = invalidCount + 1;
            continue;
        }
        let bed: Text = parts[0];
        let species: Text = parts[1];
        let dayStr: Text = parts[2];
        let countStr: Text = parts[3];

        let (day, dayOk) = try_parse_int(dayStr);
        let (count, countOk) = try_parse_int(countStr);

        let bedOk: Bool = string_len(bed) > 0 && bed[0] == "B";
        let dayValid: Bool = dayOk && day >= 1 && day <= 366;
        let countValid: Bool = countOk && count > 0;

        if bedOk && dayValid && countValid {
            validCount = validCount + 1;
            totalPlants = totalPlants + count;
            if day <= 181 {
                springCount = springCount + 1;
            } else {
                summerCount = summerCount + 1;
            }
            if earliest == 0 || day < earliest {
                earliest = day;
            }
            let found: Bool = false;
            loop j in 0..length(speciesList) {
                if speciesList[j] == species {
                    speciesCounts[j] = speciesCounts[j] + 1;
                    found = true;
                    break;
                }
            }
            if !found {
                speciesList = speciesList + [species];
                speciesCounts = speciesCounts + [1];
            }
        } else {
            invalidCount = invalidCount + 1;
        }
    }

    let mostCommon: Text = "NONE";
    if length(speciesList) > 0 {
        let bestIdx: Int = 0;
        let bestCount: Int = speciesCounts[0];
        loop j in 1..length(speciesList) {
            if speciesCounts[j] > bestCount {
                bestCount = speciesCounts[j];
                bestIdx = j;
            }
        }
        mostCommon = speciesList[bestIdx];
    }

    fx {
        println("Valid entries: ", validCount);
        println("Invalid entries: ", invalidCount);
        println("Total plants: ", totalPlants);
        println("Spring entries: ", springCount);
        println("Summer entries: ", summerCount);
        println("Most common species: ", mostCommon);
        println("Earliest planting: ", earliest);
    }
    ret;
}

