            println("Average order value: 0.00");
            println("Most expensive single item: 0.00");
            println("Best-selling size: S");
        }
        ret;
    }

    let lines: Text[] = [];
    fx { lines = read_lines("orders.txt"); }

    let validCount: Int = 0;
    let invalidCount: Int = 0;
    let totalRevenue: Real = 0.0;
    let maxPrice: Real = 0.0;
    let sQty: Int = 0;
    let mQty: Int = 0;
    let lQty: Int = 0;

    loop line in lines {
        let trimmed: Text = trim(line);
        if trimmed == "" {
            continue;
        }
        let parts: Text[] = split(trimmed, " ");
        if length(parts) != 4 {
            invalidCount = invalidCount + 1;
            continue;
        }
        let drink: Text = parts[0];
        let size: Text = parts[1];
        let priceText: Text = parts[2];
        let qtyText: Text = parts[3];

        let (price, priceOk) = try_parse_real(priceText);
        let (qty, qtyOk) = try_parse_int(qtyText);

        if !priceOk || !qtyOk || qty < 1 || (size != "S" && size != "M" && size != "L") {
            invalidCount = invalidCount + 1;
            continue;
        }

        validCount = validCount + 1;
        totalRevenue = totalRevenue + price * qty;
        if price > maxPrice {
            maxPrice = price;
        }
        if size == "S" {
            sQty = sQty + qty;
        }
        if size == "M" {
            mQty = mQty + qty;
        }
        if size == "L" {
            lQty = lQty + qty;
        }
    }

    let avg: Real = 0.0;
    if validCount > 0 {
        avg = totalRevenue / validCount;
    }

    let bestSize: Text = "S";
    if mQty > sQty {
        bestSize = "M";
    }
    if lQty > sQty && lQty > mQty {
        bestSize = "L";
    }

    fx {
        println("Total valid orders: ", validCount);
        println("Invalid lines: ", invalidCount);
        println("Total revenue: ", formatfloat(round_to(totalRevenue, 2), 2));
        println("Average order value: ", formatfloat(round_to(avg, 2), 2));
        println("Most expensive single item: ", formatfloat(round_to(maxPrice, 2), 2));
        println("Best-selling size: ", bestSize);
    }
    ret;
}

