    let totalBikes: Int = 0;
    let noBikes: Int = 0;
    let noDocks: Int = 0;
    let busiestId: Text = "";
    let busiestBikes: Int = -1;
    let totalDocks: Int = 0;

    loop line in lines {
        let trimmed: Text = trim(line);
