            continue;
        }
        let parts: Text[] = split(trimmed, " ");
        if length(parts) != 4 {
            invalidCount = invalidCount + 1;
            continue;
        }
        let (bikes, okBikes) = try_parse_int(parts[1]);
        let (docks, okDocks) = try_parse_int(parts[2]);
        let (capacity, okCap) = try_parse_int(parts[3]);
        if !okBikes || !okDocks || !okCap {
            invalidCount = invalidCount + 1;
            continue;
        }
        if bikes < 0 || docks < 0 || bikes + docks != capacity {
            invalidCount = invalidCount + 1;
            continue;
        }
        validCount = validCount + 1;
        totalBikes = totalBikes + bikes;
        totalDocks = totalDocks + docks;
        if bikes == 0 {
            noBikes = noBikes + 1;
        }
        if docks == 0 {
            noDocks = noDocks + 1;
        }
        if bikes > busiestBikes {
            busiestBikes = bikes;
            busiestId = parts[0];
        }
    }

    let avgDocks: Real = 0.0;
    if validCount > 0 {
        avgDocks = totalDocks * 1.0 / validCount;
    }

