fn isQualified(d1: Int, d2: Int, d3: Int) -> Bool {
    let hasPair: Bool = (d1 == d2) || (d1 == d3) || (d2 == d3);
    let total: Int = d1 + d2 + d3;
    let isMultipleOf3: Bool = total % 3 == 0;
    ret hasPair || isMultipleOf3;
}

