fn main() -> Void {
    let costs: Int[] = [34, 12, 34, 7, 45, 12, 7, 34];
    let n: Int = length(costs);
    let indices: Int[] = [];
    loop i in 0..n {
        indices = indices + [i + 1];
    }

    // Insertion sort: sort by cost ascending, tie-break by index ascending
    loop i in 1..n {
        let keyCost: Int = costs[i];
        let keyIdx: Int = indices[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if costs[j] > keyCost || (costs[j] == keyCost && indices[j] > keyIdx) {
                costs[j + 1] = costs[j];
                indices[j + 1] = indices[j];
                j = j - 1;
            } else {
                break;
            }
        }
        costs[j + 1] = keyCost;
        indices[j + 1] = keyIdx;
    }

    fx {
        loop i in 0..n {
            println("MOVE ", indices[i], " COST ", costs[i]);
        }
    }
    ret;
}

type Cartridge {
    num: Int = 0;
    ink: Int = 0;
}

fn main() -> Void {
    let carts: Cartridge[] = [
        new Cartridge { num: 1, ink: 85 },
        new Cartridge { num: 2, ink: 92 },
        new Cartridge { num: 3, ink: 85 },
        new Cartridge { num: 4, ink: 60 },
        new Cartridge { num: 5, ink: 92 },
        new Cartridge { num: 6, ink: 60 },
        new Cartridge { num: 7, ink: 85 },
        new Cartridge { num: 8, ink: 92 }
    ];

    // Insertion sort: descending by ink, ascending by num for ties
    loop i in 1..length(carts) {
        let key: Cartridge = carts[i];
        let j: Int = i - 1;
        loop j >= 0 {
            let cur: Cartridge = carts[j];
            let shouldSwap: Bool = false;
            if cur.ink < key.ink {
                shouldSwap = true;
            } else if cur.ink == key.ink && cur.num > key.num {
                shouldSwap = true;
            }
            if shouldSwap {
                carts[j + 1] = cur;
                j = j - 1;
            } else {
                break;
            }
        }
        carts[j + 1] = key;
    }

    // Assign ranks: same ink => same rank, next rank skips
    let rank: Int = 1;
    loop i in 0..length(carts) {
        if i > 0 && carts[i].ink != carts[i - 1].ink {
            rank = i + 1;
        }
        fx {
            println("CART ", carts[i].num, " INK ", carts[i].ink, " RANK ", rank);
        }
    }

    ret;
}

