    loop i in 0..n - 1 {
        let minIdx: Int = i;
        loop j in i + 1..n {
            if counts[j] < counts[minIdx] {
                minIdx = j;
            }
        }
        if minIdx != i {
            let tmpC: Int = counts[i];
            counts[i] = counts[minIdx];
            counts[minIdx] = tmpC;
            let tmpL: Int = levels[i];
            levels[i] = levels[minIdx];
            levels[minIdx] = tmpL;
        }
    }

    fx {
        loop i in 0..n {
            println("L", levels[i], " OCC ", counts[i]);
        }
    }
    ret;
