    loop i in 0..n {
        let idx: Int = thicknesses[i] - minT;
        let pos: Int = positions[idx];
        sortedIdx[pos] = i;
        positions[idx] = pos + 1;
    }

    fx {
        loop i in 0..n {
            let orig: Int = sortedIdx[i] + 1;
            let thick: Int = thicknesses[sortedIdx[i]];
            println("STACK ", orig, " THICK ", thick);
        }
    }
    ret;
}

