    let parts: Text[] = split(seq, " ");
    let lidOpen: Bool = false;
    let poured: Bool = false;
    let cycles: Int = 0;
    let ignored: Int = 0;

    loop cmd in parts {
        if cmd == "L" {
            if lidOpen {
                if poured {
                    lidOpen = false;
                    poured = false;
                } else {
                    ignored = ignored + 1;
                }
            } else {
                lidOpen = true;
            }
        } else if cmd == "D" {
            if lidOpen && !poured {
                poured = true;
            } else {
                ignored = ignored + 1;
            }
        } else if cmd == "S" {
            if !lidOpen && poured {
                cycles = cycles + 1;
                poured = false;
            } else {
                ignored = ignored + 1;
            }
        } else {
            ignored = ignored + 1;
        }
    }

    fx {
        println("CompletedCycles: ", cycles);
        println("IgnoredCommands: ", ignored);
    }
    ret;
}

