        let rest: Text = line[colonIdx + 1..];

        let commaIdx: Int = index_of(rest, ",");
        let adultsPart: Text = rest[0..commaIdx];
        let childrenPart: Text = rest[commaIdx + 1..];

        let adultsEq: Int = index_of(adultsPart, "=");
        let childrenEq: Int = index_of(childrenPart, "=");

        let adults: Int = parse_int(adultsPart[adultsEq + 1..]);
        let children: Int = parse_int(childrenPart[childrenEq + 1..]);

        let total: Int = adults + children;
        grandTotal = grandTotal + total;

        if total > maxTotal {
            maxTotal = total;
            maxFamily = name;
        }

        if children > adults {
            moreChildren = moreChildren + 1;
        }
    }

    fx {
        println("GrandTotal=", grandTotal);
        println("MaxFamily=", maxFamily);
        println("MoreChildrenThanAdults=", moreChildren);
    }
    ret;
}

fn main() -> Void {
    let lines: Text[] = [
        "temp=14.5,wind=12,hum=65",
        "temp=18.2,wind=8,hum=72",
        "temp=21.7,wind=15,hum=58",
        "temp=16.3,wind=22,hum=80",
        "temp=12.8,wind=5,hum=88",
        "temp=19.4,wind=18,hum=61",
        "temp=23.1,wind=10,hum=55"
    ];

    let totalTemp: Real = 0.0;
    let maxWind: Int = 0;
    let humidityAtLeast70: Int = 0;
    let warmAndCalm: Int = 0;
    let count: Int = length(lines);

    loop i in 0..count {
        let parts: Text[] = split(lines[i], ",");
        let tempPart: Text[] = split(parts[0], "=");
        let windPart: Text[] = split(parts[1], "=");
        let humPart: Text[] = split(parts[2], "=");

        let temp: Real = parse_float(tempPart[1]);
        let wind: Int = parse_int(windPart[1]);
        let hum: Int = parse_int(humPart[1]);

        totalTemp = totalTemp + temp;
        if wind > maxWind {
            maxWind = wind;
        }
        if hum >= 70 {
            humidityAtLeast70 = humidityAtLeast70 + 1;
        }
        if temp > 17.0 && wind < 15 {
            warmAndCalm = warmAndCalm + 1;
        }
    }

    let avgTemp: Real = totalTemp / count;

    fx {
        println("AvgTemp=", formatfloat(avgTemp, 2));
        println("MaxWind=", maxWind);
        println("HumidityAtLeast70=", humidityAtLeast70);
        println("WarmAndCalm=", warmAndCalm);
    }
    ret;
}

