@pure
fn hasSeven(n: Int) -> Bool {
    let x: Int = n;
    if x < 0 {
        x = -x;
    }
    loop {
        if x % 10 == 7 {
            ret true;
        }
        if x < 10 {
            ret false;
        }
        x = x div 10;
    }
}

