            hum = int(hum_s)
            light = int(light_s)
        except ValueError:
            invalid += 1
            continue
        if not (0 <= hum <= 100):
            invalid += 1
            continue
        if soil not in ('wet', 'ok', 'dry'):
            invalid += 1
            continue
        valid.append((zone, temp, hum, light, soil))

    n = len(valid)
