fn main() -> Void {
    let n: Int = 9;
    let blocked: Int[] = [4, 7];
    let dp: Int[] = [0; n + 1];
    dp[0] = 1;
    loop i in 1..n + 1 {
        let isBlocked: Bool = contains(blocked, i);
        if isBlocked {
            dp[i] = 0;
        } else {
            let ways: Int = 0;
            if i - 1 >= 0 {
                ways = ways + dp[i - 1];
            }
            if i - 2 >= 0 {
                ways = ways + dp[i - 2];
            }
            dp[i] = ways;
        }
    }
    fx {
        println("Blocked steps: 4, 7");
        println("Ways to reach step 9: ", dp[n]);
    }
    ret;
}

