fn main() -> Void {
    let spaces: Int[] = [5, 3, 8, 2, 6];
    let n: Int = length(spaces);
    let dp: Int[] = [];
    loop i in 0..n {
        dp = dp + [0];
    }
    dp[0] = spaces[0];
    loop i in 1..n {
        let best: Int = 0;
        if i >= 1 {
            best = dp[i - 1] + spaces[i];
        }
        if i >= 2 {
            let alt: Int = dp[i - 2] + spaces[i];
            if alt > best {
                best = alt;
            }
        }
        dp[i] = best;
    }
    fx {
        println("Max free spaces passed: ", dp[n - 1]);
    }
    ret;
}

