fn main() -> Void {
    let tomato: Int[] = [3, 4, 2, 5, 1, 3];
    let basil: Int[] = [2, 1, 3, 2, 4, 2];
    let n: Int = 6;
    let best: Int = 999999;

    loop mask in 0..(1 << n) {
        let ok: Bool = true;
        loop i in 0..(n - 1) {
            let a: Int = (mask >> i) & 1;
            let b: Int = (mask >> (i + 1)) & 1;
            if a == 1 && b == 1 {
                ok = false;
            }
        }
        if ok {
            let total: Int = 0;
            loop i in 0..n {
                let bit: Int = (mask >> i) & 1;
                if bit == 1 {
                    total = total + tomato[i];
                } else {
                    total = total + basil[i];
                }
            }
            if total < best {
                best = total;
            }
        }
    }

    fx {
        println("Min water: ", best);
    }
    ret;
}

