fn main() -> Void {
    let occupied: Int[] = [1, 2, 5, 6, 7, 10];
    let runs: Int[][] = [];
    let i: Int = 1;
    loop i < 11 {
        let isFree: Bool = !contains(occupied, i);
        if isFree {
            let start: Int = i;
            let end: Int = i;
            loop j in i + 1..11 {
                if contains(occupied, j) {
                    break;
                }
                end = j;
            }
            let row: Int[] = [start, end];
            runs = runs + [row];
            i = end + 1;
        } else {
            i = i + 1;
        }
    }
    fx {
        loop r in 0..length(runs) {
            let start: Int = runs[r][0];
            let end: Int = runs[r][1];
            let len: Int = end - start + 1;
            println("RUN=" + int_to_text(start) + "-" + int_to_text(end) + " LENGTH=" + int_to_text(len));
        }
    }
    ret;
}

