    loop k in 0..n {
        loop i in 0..n {
            loop j in 0..n {
                loop e in 0..m {
                    if from[e] == i && to[e] == j {
                        if dist[i] + wt[e] < dist[j] {
                            dist[j] = dist[i] + wt[e];
                        }
                    }
                }
            }
        }
    }

    loop s in 0..n {
