fn legTime(from: Int, to: Int, m: Int[][]) -> Int {
    let direct: Int = m[from][to];
    if direct > 0 {
        ret direct;
    }
    let best: Int = 999999;
    loop k in 0..4 {
        if k == from || k == to {
            continue;
        }
        let a: Int = m[from][k];
        let b: Int = m[k][to];
        if a > 0 && b > 0 {
            let s: Int = a + b;
            if s < best {
                best = s;
            }
        }
    }
    ret best;
}

