fn main() -> Void {
    let titles: Text[] = ["Sunrise Drive", "Midnight Rain", "Sunrise Drive", "Ocean Breeze", "Midnight Rain", "Sunset Boulevard", "Midnight Rain", "Ocean Breeze", "Sunrise Drive", "Sunset Boulevard", "Ocean Breeze", "Sunrise Drive"];
    let durations: Int[] = [210, 195, 180, 240, 225, 260, 175, 200, 190, 230, 215, 170];
    let n: Int = length(titles);

    // Count occurrences of each title
    let uniqueTitles: Text[] = [];
    let counts: Int[] = [];
    loop i in 0..n {
        let t: Text = titles[i];
        let found: Bool = false;
        loop j in 0..length(uniqueTitles) {
            if uniqueTitles[j] == t {
                counts[j] = counts[j] + 1;
                found = true;
                break;
            }
        }
        if !found {
            uniqueTitles = uniqueTitles + [t];
            counts = counts + [1];
        }
    }

    // Repeat titles: count of titles appearing more than once
    let repeats: Int = 0;
    loop j in 0..length(counts) {
        if counts[j] > 1 {
            repeats = repeats + 1;
        }
    }

    // First title that appears again later
    let firstRepeat: Text = "";
    loop i in 0..n {
        let t: Text = titles[i];
        let seenAgain: Bool = false;
        loop k in i + 1..n {
            if titles[k] == t {
                seenAgain = true;
                break;
            }
        }
        if seenAgain {
            firstRepeat = t;
            break;
        }
    }

    // Longest contiguous run of same title
    let maxRun: Int = 1;
    let curRun: Int = 1;
    loop i in 1..n {
        if titles[i] == titles[i - 1] {
            curRun = curRun + 1;
            if curRun > maxRun {
                maxRun = curRun;
            }
        } else {
            curRun = 1;
        }
    }

    // Total duration
    let total: Int = 0;
    loop i in 0..n {
        total = total + durations[i];
    }

    fx {
        println("Repeat titles: ", repeats);
        println("First title: ", firstRepeat);
        println("Longest same-title run: ", maxRun);
        println("Total duration: ", total);
    }
    ret;
}

