            if ch == prevCh {
                currentRun = currentRun + 1;
            } else {
                currentRun = 1;
            }
        }
        if currentRun > longestRun {
            longestRun = currentRun;
        }
        prevCh = ch;
    }

    let distinct: Int = 0;
    loop i in 0..26 {
        if counts[i] > 0 {
            distinct = distinct + 1;
        }
