type Track {
    title: Text = "";
    duration: Int = 0;
}

@pure
fn compareTracks(a: Track, b: Track) -> Int {
    if a.duration < b.duration {
        ret -1;
    }
    if a.duration > b.duration {
        ret 1;
    }
    if a.title < b.title {
        ret -1;
    }
    if a.title > b.title {
        ret 1;
    }
    ret 0;
}

@pure
fn sortTracks(tracks: Track[]) -> Track[] {
    let n: Int = length(tracks);
    let result: Track[] = tracks;
    loop i in 0..n {
        loop j in 0..n - i - 1 {
            if compareTracks(result[j], result[j + 1]) > 0 {
                let tmp: Track = result[j];
                result[j] = result[j + 1];
                result[j + 1] = tmp;
            }
        }
    }
    ret result;
}

