            let ways: Int = 0;
            if r > 0 {
                ways = ways + dp[r - 1][c];
            }
            if c > 0 {
                ways = ways + dp[r][c - 1];
            }
            dp[r][c] = ways;
        }
    }

    fx {
        println("Routes to R3C10: ", dp[2][9]);
    }
    ret;
}

fn main() -> Void {
    let count: Int = 0;
    // Subjects: 0=Math, 1=Science, 2=English, 3=Art
    // Try all permutations of [0,1,2,3] and all choices of which subject gets 2 periods
    loop s0 in 0..4 {
        loop s1 in 0..4 {
            if s1 == s0 { continue; }
            loop s2 in 0..4 {
                if s2 == s0 or s2 == s1 { continue; }
                loop s3 in 0..4 {
                    if s3 == s0 or s3 == s1 or s3 == s2 { continue; }
                    // Now we have a permutation [s0, s1, s2, s3]
                    // Try each subject as the one with 2 periods
                    loop doubleIdx in 0..4 {
                        // Build the period assignments
                        // Periods 1-5, assign subjects based on order and which gets 2
                        let p1: Int = -1;
                        let p2: Int = -1;
                        let p3: Int = -1;
                        let p4: Int = -1;
                        let p5: Int = -1;
                        let pos: Int = 0;
                        // Process each subject in order
                        // Subject at index 0
                        if doubleIdx == 0 {
                            p1 = s0;
                            p2 = s0;
                            pos = 2;
                        } else {
                            p1 = s0;
                            pos = 1;
                        }
                        // Subject at index 1
                        if doubleIdx == 1 {
                            if pos == 1 {
                                p2 = s1;
                                p3 = s1;
                            } else if pos == 2 {
                                p3 = s1;
                                p4 = s1;
                            } else if pos == 3 {
                                p4 = s1;
                                p5 = s1;
                            }
                            pos = pos + 2;
                        } else {
                            if pos == 1 {
                                p2 = s1;
                            } else if pos == 2 {
                                p3 = s1;
                            } else if pos == 3 {
                                p4 = s1;
                            } else if pos == 4 {
                                p5 = s1;
                            }
                            pos = pos + 1;
                        }
                        // Subject at index 2
                        if doubleIdx == 2 {
                            if pos == 1 {
                                p2 = s2;
                                p3 = s2;
                            } else if pos == 2 {
                                p3 = s2;
                                p4 = s2;
                            } else if pos == 3 {
                                p4 = s2;
                                p5 = s2;
                            }
                            pos = pos + 2;
                        } else {
                            if pos == 1 {
                                p2 = s2;
                            } else if pos == 2 {
                                p3 = s2;
                            } else if pos == 3 {
                                p4 = s2;
                            } else if pos == 4 {
                                p5 = s2;
                            }
                            pos = pos + 1;
                        }
                        // Subject at index 3
                        if doubleIdx == 3 {
                            if pos == 1 {
                                p2 = s3;
                                p3 = s3;
                            } else if pos == 2 {
                                p3 = s3;
                                p4 = s3;
                            } else if pos == 3 {
                                p4 = s3;
                                p5 = s3;
                            }
                            pos = pos + 2;
                        } else {
                            if pos == 1 {
                                p2 = s3;
                            } else if pos == 2 {
                                p3 = s3;
                            } else if pos == 3 {
                                p4 = s3;
                            } else if pos == 4 {
                                p5 = s3;
                            }
                            pos = pos + 1;
                        }
                        // Check all periods are assigned
                        if p1 == -1 or p2 == -1 or p3 == -1 or p4 == -1 or p5 == -1 {
                            continue;
                        }
                        // Check forbidden constraints
                        // Math=0 in P4
                        if p4 == 0 { continue; }
                        // Science=1 in P1
                        if p1 == 1 { continue; }
                        // English=2 in P5
                        if p5 == 2 { continue; }
                        // Art=3 in P1
                        if p1 == 3 { continue; }
                        // Art=3 in P3
                        if p3 == 3 { continue; }
                        count = count + 1;
                    }
                }
            }
        }
    }
    fx {
        println("Valid timetables: ", count);
    }
    ret;
}

fn main() -> Void {
    let count: Int = 0;
    loop mask in 0..256 {
        let ok: Bool = true;
        if (mask & 1) == 0 {
            ok = false;
        }
        if (mask & 128) == 0 {
            ok = false;
        }
        if (mask & 4) != 0 {
            ok = false;
        }
        if (mask & 32) != 0 {
            ok = false;
        }
        if ok {
            let adj: Int = 0;
            loop i in 0..7 {
                if (mask & (1 << i)) != 0 {
                    if (mask & (1 << (i + 1))) != 0 {
                        adj = 1;
                    }
                }
            }
            if adj == 0 {
                count = count + 1;
            }
        }
    }
    fx {
        println("Valid station sets: ", count);
    }
    ret;
}

fn main() -> Void {
    let count: Int = 0;
    loop m in 0..512 {
        let ok: Bool = true;
        if (m & 1) == 0 {
            ok = false;
        }
        if (m & 256) == 0 {
            ok = false;
        }
        if (m & 8) != 0 {
            ok = false;
        }
        if (m & 64) != 0 {
            ok = false;
        }
        if ok {
            let prev: Int = -1;
            let valid: Bool = true;
            loop i in 0..9 {
                let bit: Int = 1 << i;
                if (m & bit) != 0 {
                    if prev >= 0 {
                        let gap: Int = i - prev;
                        if gap != 1 && gap != 3 {
                            valid = false;
                        }
                    }
                    prev = i;
                }
            }
            if valid {
                count = count + 1;
            }
        }
    }
    fx {
        println("Valid stone layouts: ", count);
    }
    ret;
}

