        new Student { num: 2, grade: 6, bal: 8.00 },
        new Student { num: 3, grade: 4, bal: 15.00 },
        new Student { num: 4, grade: 6, bal: 8.00 },
        new Student { num: 5, grade: 5, bal: 10.25 },
        new Student { num: 6, grade: 4, bal: 9.75 },
        new Student { num: 7, grade: 6, bal: 11.00 },
        new Student { num: 8, grade: 5, bal: 7.50 }
    ];

    // insertion sort with custom comparator
    let n: Int = length(students);
    loop i in 1..n {
        let key: Student = students[i];
        let j: Int = i - 1;
        loop {
            if j < 0 {
                break;
            }
            let cur: Student = students[j];
            let swapNeeded: Bool = false;
            if cur.grade < key.grade {
                swapNeeded = true;
            } else if cur.grade == key.grade {
                if cur.bal < key.bal {
                    swapNeeded = true;
                } else if cur.bal == key.bal {
                    if cur.num > key.num {
                        swapNeeded = true;
                    }
                }
            }
            if !swapNeeded {
                break;
            }
            students[j + 1] = students[j];
            j = j - 1;
        }
        students[j + 1] = key;
    }

