}

@pure
fn computeFee(minutes: Int, rate: Int) -> Int {
    let hours: Int = (minutes + 59) div 60;
    ret hours * rate;
}

fn main() -> Void {
    let tickets: Ticket[] = [
        new Ticket { num: 1, minutes: 45, rate: 3 },
        new Ticket { num: 2, minutes: 120, rate: 2 },
        new Ticket { num: 3, minutes: 75, rate: 3 },
