        new Ticket { num: 6, minutes: 90, rate: 3 },
        new Ticket { num: 7, minutes: 150, rate: 2 },
        new Ticket { num: 8, minutes: 60, rate: 3 }
    ];

    loop i in 0..length(tickets) {
        tickets[i].fee = computeFee(tickets[i].minutes, tickets[i].rate);
    }

    // insertion sort: fee descending, then num ascending
    loop i in 1..length(tickets) {
        let key: Ticket = tickets[i];
        let j: Int = i - 1;
        loop {
            if j < 0 {
                break;
            }
            if tickets[j].fee > key.fee {
                break;
            }
            if tickets[j].fee == key.fee && tickets[j].num <= key.num {
                break;
            }
            tickets[j + 1] = tickets[j];
            j = j - 1;
        }
        tickets[j + 1] = key;
    }

    fx {
        loop i in 0..length(tickets) {
            println("T", tickets[i].num, " fee=", tickets[i].fee);
        }
    }
    ret;
}

