fn main() -> Void {
    let matches: Text[] = ["Elena;Marco;1-0", "Sofia;James;1/2-1/2", "Marco;Sofia;0-1", "James;Elena;0-1", "Elena;Sofia;1-0"];
    let names: Text[] = [];
    let games: Int[] = [];
    let scores: Real[] = [];

    loop m in matches {
        let parts: Text[] = split(m, ";");
        let white: Text = parts[0];
        let black: Text = parts[1];
        let result: Text = parts[2];

        let wi: Int = index_of(names, white);
        if wi == -1 {
            names = names + [white];
            games = games + [0];
            scores = scores + [0.0];
            wi = length(names) - 1;
        }
        let bi: Int = index_of(names, black);
        if bi == -1 {
            names = names + [black];
            games = games + [0];
            scores = scores + [0.0];
            bi = length(names) - 1;
        }

        games[wi] = games[wi] + 1;
        games[bi] = games[bi] + 1;

        if result == "1-0" {
            scores[wi] = scores[wi] + 1.0;
        } else {
            if result == "0-1" {
                scores[bi] = scores[bi] + 1.0;
            } else {
                scores[wi] = scores[wi] + 0.5;
                scores[bi] = scores[bi] + 0.5;
            }
        }
    }

    let order: Int[] = [];
    loop i in 0..length(names) {
        order = order + [i];
    }
    loop i in 0..length(order) {
        loop j in 0..(length(order) - 1 - i) {
            if names[order[j]] > names[order[j + 1]] {
                let tmp: Int = order[j];
                order[j] = order[j + 1];
                order[j + 1] = tmp;
            }
        }
    }

    fx {
        loop k in order {
            println(names[k], ": ", games[k], " games, ", formatfloat(scores[k], 1));
        }
    }
    ret;
}

fn main() -> Void {
    let records: Text[] = ["Liu|5|1450", "Liu|10|2980", "Liu|21|6300", "Mia|5|1520", "Mia|10|3150", "Mia|21|6700"];

    let names: Text[] = [];
    let kms: Int[] = [];
    let times: Int[] = [];

    loop rec in records {
        let parts: Text[] = split(rec, "|");
        let nm: Text = parts[0];
        let km: Int = parse_int(parts[1]);
        let t: Int = parse_int(parts[2]);
        if !contains(names, nm) {
            names = names + [nm];
        }
        kms = kms + [km];
        times = times + [t];
    }

    let seg: Int[] = [0; length(names)];

    loop i in 0..length(records) {
        let parts: Text[] = split(records[i], "|");
        let nm: Text = parts[0];
        let km: Int = parse_int(parts[1]);
        let t: Int = parse_int(parts[2]);
        let idx: Int = index_of(names, nm);
        if seg[idx] > 0 {
            let prevKm: Int = 0;
            let prevT: Int = 0;
            let count: Int = 0;
            loop j in 0..i {
                let pj: Text[] = split(records[j], "|");
                if pj[0] == nm {
                    count = count + 1;
                    if count == seg[idx] {
                        prevKm = parse_int(pj[1]);
                        prevT = parse_int(pj[2]);
                    }
                }
            }
            let pace: Real = (t - prevT) * 1.0 / (km - prevKm);
            fx {
                println(nm, " segment ", seg[idx], " pace: ", formatfloat(pace, 1));
            }
        }
        seg[idx] = seg[idx] + 1;
    }

    ret;
}

