type Swimmer {
    name: Text = "";
    time: Real = 0.0;
}

fn main() -> Void {
    let records: Text[] = ["Ana:34.5", "Ben:41.2", "Cara:33.8", "Dan:39.6"];
    let swimmers: Swimmer[] = [];

    loop rec in records {
        let parts: Text[] = split(rec, ":");
        let s: Swimmer = new Swimmer { name: parts[0], time: parse_float(parts[1]) };
        swimmers = swimmers + [s];
    }

    // insertion sort by time ascending
    loop i in 1..length(swimmers) {
        let key: Swimmer = swimmers[i];
        let j: Int = i - 1;
        loop j >= 0 && swimmers[j].time > key.time {
            swimmers[j + 1] = swimmers[j];
            j = j - 1;
        }
        swimmers[j + 1] = key;
    }

    let total: Real = 0.0;
    loop s in swimmers {
        total = total + s.time;
    }
    let avg: Real = total / length(swimmers);

    fx {
        loop i in 0..length(swimmers) {
            println(i + 1, ". ", swimmers[i].name, " ", formatfloat(swimmers[i].time, 1));
        }
        println("Average: ", formatfloat(avg, 1));
    }
    ret;
}

fn main() -> Void {
    let commands: Text[] = ["N3", "E2", "S1", "W4", "N5", "E6"];
    let x: Int = 0;
    let y: Int = 0;
    let total: Int = 0;
    let away: Int = 0;

    loop cmd in commands {
        let dir: Text = cmd[0];
        let dist: Int = parse_int(cmd[1..]);
        let oldDist: Int = x * x + y * y;

        if dir == "N" {
            y = y + dist;
        }
        if dir == "S" {
            y = y - dist;
        }
        if dir == "E" {
            x = x + dist;
        }
        if dir == "W" {
            x = x - dist;
        }

        total = total + dist;
        let newDist: Int = x * x + y * y;
        if newDist > oldDist {
            away = away + 1;
        }
    }

    fx {
        println("Final X: ", x);
        println("Final Y: ", y);
        println("Total Distance: ", total);
        println("Away Moves: ", away);
    }
    ret;
}

