    if tempC < 0 { ret "alert"; }
    if tempC >= 28 { ret "warn"; }
    ret "normal";
}

type Telemetry {
    count: Int;
    sumTemp: Int;
    normal: Int;
    warn: Int;
    alert: Int;

    fn record(status: Text, tempC: Int) -> Void {
        self.count = self.count + 1;
