// 34_toon_stats
// Concepts: accumulate over a TOON array, real-valued rate via 100.0,
// stable decimal output
// expect: transactions = 4
// expect: total = 545
// expect: large share = 50.00 %

fn main() -> Void {
    if !has_toon() { fx { println("yyjson unavailable"); } ret; }

    let doc: ToonDoc = toon_parse("{\"transactions\":[{\"amount\":120},{\"amount\":80},{\"amount\":45},{\"amount\":300}]}");
    let root: ToonNode = toon_root(doc);
    let transactions: ToonNode = toon_key(root, "transactions");

    let count: Int = toon_len(transactions);
    let total: Int = 0;
    let large: Int = 0;

    loop i in 0..count {
        let tx: ToonNode = toon_at(transactions, i);
        let amount: Int = toon_get_int_or(tx, "amount", 0);
        total = total + amount;
        if amount >= 100 { large = large + 1; }
    }

    let largeShare: Real = large * 100.0 / count;

    fx {
        println("transactions = ", count);
        println("total = ", total);
        println("large share = ", largeShare:0:2, "%");
    }

    toon_close(doc);
    ret;
}

// 36_pipeline_capstone
// Concepts: end-to-end shape — pure classification, contract-guarded
// normalization, record construction from TOON rows, effectful report
// expect: alpha [ 95] -> ready
// expect: beta [ 72] -> review
// expect: gamma [ 100] -> ready
// expect: ready jobs = 2

const DefaultScore: Int = 50;

@pure
fn classify(score: Int) -> Text {
    if score >= 90 { ret "ready"; }
    if score >= 70 { ret "review"; }
    ret "blocked";
}

@pure
fn priority(score: Int) -> Int {
    if score >= 90 { ret 3; }
    if score >= 70 { ret 2; }
    ret 1;
}

@pre score >= 0
@post result >= 0
fn normalizeScore(score: Int) -> Int {
    if score > 100 { ret 100; }
    ret score;
}

type JobSummary {
    name: Text;
    score: Int;
    status: Text;
    priority: Int;

    fn isReady() -> Bool {
        ret self.priority == 3;
    }
}

fn makeSummary(job: ToonNode) -> JobSummary {
    let name: Text = toon_get_text(job, "name");
    let rawScore: Int = toon_get_int_or(job, "score", DefaultScore);
    let score: Int = normalizeScore(rawScore);
    let summary: JobSummary = new JobSummary();
    summary.name = name;
    summary.score = score;
    summary.status = classify(score);
    summary.priority = priority(score);
    ret summary;
}

fn main() -> Void {
    if !has_toon() { fx { println("yyjson unavailable"); } ret; }

    let doc: ToonDoc = toon_parse("{\"jobs\":[{\"name\":\"alpha\",\"score\":95},{\"name\":\"beta\",\"score\":72},{\"name\":\"gamma\",\"score\":150}]}");
    let root: ToonNode = toon_root(doc);
    let jobs: ToonNode = toon_key(root, "jobs");

    let readyCount: Int = 0;
