type Stats {
    total: Int = 0;
    count: Int = 0;
}

fn sum_range(stats: Stats, lo: Int, hi: Int) -> Void {
    loop i in lo..hi { stats.total = stats.total + i; stats.count = stats.count + 1; }
    ret;
}

