    is_prime: Bool;
    fact: Int;
}

@pure
fn is_prime(n: Int) -> Bool {
    if n < 2 { ret false; }
    if n == 2 { ret true; }
    if n % 2 == 0 { ret false; }
    let i: Int = 3;
    loop i * i <= n { if n % i == 0 { ret false; } i = i + 2; }
    ret true;
}

fn main() -> Void {
