// Log-line parsing with split, trim, pos, copy

@pure
fn levelOf(line: Text) -> Text {
    let parts: Text[] = split(line, "|");
    if length(parts) < 2 { ret "UNKNOWN"; }
    ret trim(parts[0]);
}

@pure
fn messageOf(line: Text) -> Text {
    let at: Int = index_of(line, "|");
    if at < 0 { ret line; }
    ret trim(line[at + 1..at + 1 + string_len(line) - at - 1]);
}

fn main() -> Void {
    let lines: Text[] = [
        "INFO  | worker started",
        "WARN  | queue depth 80%",
        "ERROR | disk full",
