fn main() -> Void {
    let text: Text = "the quick brown fox jumps over the lazy dog the fox was quick";
    let words: Text[] = [];
    let current: Text = "";

    loop i in 0..string_len(text) {
        let ch: Text = text[i..i + 1];
        if ch != " " { current = current + ch; }
        if ch == " " || i == string_len(text) - 1 {
            if string_len(current) > 0 { words = words + [current]; }
            current = "";
        }
    }

    let wordCounts: WordCount[] = [];

    loop i in 0..length(words) {
        let w: Text = words[i];
        let found: Bool = false;

        loop j in 0..length(wordCounts) {
            if wordCounts[j].wordText == w {
                wordCounts[j].count = wordCounts[j].count + 1;
                found = true;
            }
        }

        if !found { wordCounts = wordCounts + [new WordCount { wordText: w, count: 1 }]; }
    }

    fx {
        println("Word frequency analysis:");
        println("Total words: ", length(words));
        println("Unique words: ", length(wordCounts));
        println("");
        println("Word counts:");
    }

    loop i in 0..length(wordCounts) {
        let wc: WordCount = wordCounts[i];
        fx { println(wc.wordText, ": ", wc.count); }
    }
    ret;
}

type TrafficLight {
    state: Text;
    timers: Int[];

    fn currentColor() -> Text {
        ret self.state;
    }

    fn nextState() -> Void {
        if self.state == "red" { self.state = "green"; ret; }
        if self.state == "green" { self.state = "yellow"; ret; }
        self.state = "red";
        ret;
    }

    fn tick() -> Void {
        self.nextState();
        ret;
    }
}

fn makeTrafficLight() -> TrafficLight {
    ret new TrafficLight { state: "red", timers: [30, 5, 25] };
}

fn main() -> Void {
    let light: TrafficLight = makeTrafficLight();

    fx { println("Traffic Light Simulation"); println("========================"); }

    let cycles: Int = 6;
    loop i in 0..cycles {
        let color: Text = light.currentColor();
        fx { print("Cycle ", i + 1, ": "); }

        if color == "red" { fx { println("STOP"); } }
        if color == "yellow" { fx { println("CAUTION"); } }
        if color == "green" { fx { println("GO"); } }

        light.tick();
    }

    fx { println("Simulation complete"); }
    ret;
}

