fn collatzLength(n: Int) -> Int {
    let steps: Int = 0;
    let current: Int = n;
    loop current != 1 {
        if current % 2 == 0 {
            current = current / 2;
        } else {
            current = current * 3 + 1;
        }
        steps = steps + 1;
    }
    ret steps;
}

fn main() -> Void {
    let limit: Int = 100;
    let longestStart: Int = 1;
    let longestLen: Int = 0;

    fx { println("Collatz sequences for 1..", limit, ":"); }

    loop n in 1..limit + 1 {
        let len: Int = collatzLength(n);
        if len > longestLen { longestLen = len; longestStart = n; }
        if n <= 10 { fx { println("  n=", n, " steps=", len); } }
    }

    fx {
        println("");
        println("Longest chain: n=", longestStart, " with ", longestLen, " steps");
    }
    ret;
}

@pre isSorted(arr)
@post result == -1 || arr[result] == target
fn binarySearch(arr: Int[], target: Int) -> Int {
    let lo: Int = 0;
    let hi: Int = length(arr) - 1;
    loop lo <= hi {
        let mid: Int = lo + (hi - lo) / 2;
        if arr[mid] == target { ret mid; }
        if arr[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    ret -1;
}

@pure
fn isSorted(arr: Int[]) -> Bool {
    loop i in 1..length(arr) { if arr[i] < arr[i - 1] { ret false; } }
    ret true;
}

fn main() -> Void {
    let data: Int[] = [2, 5, 8, 12, 16, 23, 38, 42, 56, 72, 91];
    let targets: Int[] = [23, 50, 2, 91, 1];

    fx {
        print("Array: ");
        loop i in 0..length(data) { print(data[i], " "); }
        println("");
    }

    loop i in 0..length(targets) {
        let t: Int = targets[i];
        let idx: Int = binarySearch(data, t);
        if idx >= 0 {
            fx { println("Found ", t, " at index ", idx); }
        } else {
            fx { println(t, " not found"); }
        }
    }
    ret;
}

type Board {
    cells: Text[];

    fn get(r: Int, c: Int) -> Text {
        ret self.cells[r * 3 + c];
    }

    fn place(r: Int, c: Int, mark: Text) -> Void {
        self.cells[r * 3 + c] = mark;
        ret;
    }

    fn checkWin(mark: Text) -> Bool {
        loop r in 0..3 {
            if self.get(r, 0) == mark && self.get(r, 1) == mark && self.get(r, 2) == mark {
                ret true;
            }
        }
        loop c in 0..3 {
            if self.get(0, c) == mark && self.get(1, c) == mark && self.get(2, c) == mark {
                ret true;
            }
        }
        if self.get(0, 0) == mark && self.get(1, 1) == mark && self.get(2, 2) == mark {
            ret true;
        }
        if self.get(0, 2) == mark && self.get(1, 1) == mark && self.get(2, 0) == mark {
            ret true;
        }
        ret false;
    }

    fn isFull() -> Bool {
        loop i in 0..9 { if self.cells[i] == " " { ret false; } }
        ret true;
    }

    fn display() -> Void {
        loop r in 0..3 {
            fx { println(" ", self.get(r, 0), " | ", self.get(r, 1), " | ", self.get(r, 2)); }
            if r < 2 { fx { println("-----------"); } }
        }
        ret;
    }
}

fn makeBoard() -> Board {
    let empty: Text[] = [];
    loop i in 0..9 { empty = empty + [" "]; }
    ret new Board { cells: empty };
}

fn main() -> Void {
    let board: Board = makeBoard();
    let current: Text = "X";
    let gameOver: Bool = false;

    fx { println("Tic-Tac-Toe: X goes first"); }

    loop !gameOver {
        board.display();

        let placed: Bool = false;
        loop r in 0..3 {
            if placed { break; }
            loop c in 0..3 {
                if placed { break; }
                if board.get(r, c) == " " { board.place(r, c, current); placed = true; }
            }
        }

        if board.checkWin(current) {
            board.display();
            fx { println(current, " wins!"); }
            gameOver = true;
        } else if board.isFull() {
            board.display();
            fx { println("Draw!"); }
            gameOver = true;
        } else {
            if current == "X" {
                current = "O";
            } else {
                current = "X";
            }
        }
    }
    ret;
}

type Node {
    value: Int;
    next: Node;
}

fn makeNode(val: Int) -> Node {
    ret new Node { value: val, next: nil };
}

type LinkedList {
    head: Node;

    fn prepend(val: Int) -> Void {
        let node: Node = makeNode(val);
        node.next = self.head;
        self.head = node;
        ret;
    }

    fn append(val: Int) -> Void {
        let node: Node = makeNode(val);
        if self.head == nil { self.head = node; ret; }
        let current: Node = self.head;
        loop current.next != nil { current = current.next; }
        current.next = node;
        ret;
    }

    fn size() -> Int {
        let count: Int = 0;
        let current: Node = self.head;
        loop current != nil { count = count + 1; current = current.next; }
        ret count;
    }

    fn toText() -> Text {
        let result: Text = "[";
        let current: Node = self.head;
        let first: Bool = true;
        loop current != nil {
            if !first { result = result + ", "; }
            result = result + int_to_text(current.value);
            first = false;
            current = current.next;
        }
        ret result + "]";
    }
}

fn main() -> Void {
    let list: LinkedList = new LinkedList { head: nil };

    list.append(10);
    list.append(20);
    list.append(30);
    list.prepend(5);
    list.prepend(1);

    fx { println("List: ", list.toText()); println("Length: ", list.size()); }
    ret;
}

type Stack {
    items: Int[];

    fn push(val: Int) -> Void {
        self.items = self.items + [val];
        ret;
    }

    fn pop() -> Int {
        let top: Int = self.items[length(self.items) - 1];
        let newItems: Int[] = [];
        loop i in 0..length(self.items) - 1 { newItems = newItems + [self.items[i]]; }
        self.items = newItems;
        ret top;
    }

    fn peek() -> Int {
        ret self.items[length(self.items) - 1];
    }

    fn size() -> Int {
        ret length(self.items);
    }
}

@pure
fn isOp(ch: Text) -> Bool {
    if ch == "+" { ret true; }
    if ch == "-" { ret true; }
    if ch == "*" { ret true; }
    if ch == "/" { ret true; }
    ret false;
}

fn evalRPN(tokens: Text[]) -> Int {
    let stack: Stack = new Stack { items: [] };

    loop i in 0..length(tokens) {
        let tok: Text = tokens[i];
        if isOp(tok) {
            let b: Int = stack.pop();
            let a: Int = stack.pop();
            let result: Int = 0;
            if tok == "+" { result = a + b; }
            if tok == "-" { result = a - b; }
            if tok == "*" { result = a * b; }
            if tok == "/" { result = a / b; }
            stack.push(result);
        } else {
            stack.push(parse_int(tok));
        }
    }
    ret stack.pop();
}

fn main() -> Void {
    let expr1: Text[] = ["2", "3", "+", "4", "*"];
    let expr2: Text[] = ["5", "1", "2", "+", "4", "*", "+", "3", "-"];

    fx {
        println("Expression: 2 3 + 4 * => ", evalRPN(expr1));
        println("Expression: 5 1 2 + 4 * + 3 - => ", evalRPN(expr2));
    }
    ret;
}

type Grid {
    width: Int;
    height: Int;
    cells: Int[];

    fn idx(r: Int, c: Int) -> Int {
        ret r * self.width + c;
    }

    fn alive(r: Int, c: Int) -> Bool {
        if r < 0 || r >= self.height || c < 0 || c >= self.width { ret false; }
        ret self.cells[self.idx(r, c)] == 1;
    }

    fn countNeighbors(r: Int, c: Int) -> Int {
        let count: Int = 0;
        let dr: Int = -1;
        loop dr <= 1 {
            let dc: Int = -1;
            loop dc <= 1 {
                if dr != 0 || dc != 0 {
                    if self.alive(r + dr, c + dc) { count = count + 1; }
                }
                dc = dc + 1;
            }
            dr = dr + 1;
        }
        ret count;
    }

    fn step() -> Grid {
        let next: Int[] = [];
        loop i in 0..self.width * self.height { next = next + [0]; }
        let result: Grid = new Grid { width: self.width, height: self.height, cells: next };

        loop r in 0..self.height {
            loop c in 0..self.width {
                let n: Int = self.countNeighbors(r, c);
                let current: Int = self.cells[self.idx(r, c)];
                if current == 1 && (n == 2 || n == 3) {
                    result.cells[result.idx(r, c)] = 1;
                }
                if current == 0 && n == 3 { result.cells[result.idx(r, c)] = 1; }
            }
        }
        ret result;
    }

    fn display() -> Void {
        loop r in 0..self.height {
            let line: Text = "";
            loop c in 0..self.width {
                if self.alive(r, c) {
                    line = line + "# ";
                } else {
                    line = line + ". ";
                }
            }
            fx { println(line); }
        }
        ret;
    }
}

fn main() -> Void {
    let w: Int = 10;
    let h: Int = 6;
    let cells: Int[] = [];
    loop i in 0..w * h { cells = cells + [0]; }
    let grid: Grid = new Grid { width: w, height: h, cells: cells };

    grid.cells[grid.idx(1, 2)] = 1;
    grid.cells[grid.idx(2, 3)] = 1;
    grid.cells[grid.idx(3, 1)] = 1;
    grid.cells[grid.idx(3, 2)] = 1;
    grid.cells[grid.idx(3, 3)] = 1;

    let generations: Int = 5;
    loop gen in 0..generations {
        fx { println("--- Generation ", gen, " ---"); }
        grid.display();
        grid = grid.step();
    }
    fx { println("--- Final ---"); }
    grid.display();
    ret;
}

// Line/word/char counter over an in-memory Text[] of lines. Aether exposes
// no readable "file variable" type from its own syntax (assign/reset/readln
// are real vm_builtins, but "First arg to Assign must be a file variable"
// -- there is no Aether-level file-content-read API), so this demonstrates
// the counting logic directly rather than pretending to open a real file.
fn main() -> Void {
    let lines: Text[] = [
        "the quick brown fox",
        "jumps over the lazy dog",
        "aether is a compact language"
    ];

    let lineCount: Int = 0;
    let wordCount: Int = 0;
    let charCount: Int = 0;

    loop li in 0..length(lines) {
        let line: Text = lines[li];
        lineCount = lineCount + 1;
        charCount = charCount + string_len(line);

        let words: Text[] = split(line, " ");
        loop wi in 0..length(words) {
            if string_len(words[wi]) > 0 { wordCount = wordCount + 1; }
        }
    }

    fx {
        println("Lines: ", lineCount);
        println("Words: ", wordCount);
        println("Chars: ", charCount);
    }
    ret;
}

type Account {
    id: Int;
    owner: Text;
    balance: Real;

    fn deposit(amount: Real) -> Bool {
        if amount <= 0.0 { ret false; }
        self.balance = self.balance + amount;
        ret true;
    }

    fn withdraw(amount: Real) -> Bool {
        if amount <= 0.0 || amount > self.balance { ret false; }
        self.balance = self.balance - amount;
        ret true;
    }

    fn transfer(to: Account, amount: Real) -> Bool {
        if !self.withdraw(amount) { ret false; }
        if !to.deposit(amount) { self.deposit(amount); ret false; }
        ret true;
    }

    fn print() -> Void {
        fx {
            println("Account ", self.id, " (", self.owner, "): ", formatfloat(self.balance, 2));
        }
        ret;
    }
}

fn main() -> Void {
    let alice: Account = new Account { id: 1, owner: "Alice", balance: 1000.0 };
    let bob: Account = new Account { id: 2, owner: "Bob", balance: 500.0 };

    alice.print();
    bob.print();

    alice.deposit(200.0);
    bob.withdraw(100.0);

    alice.transfer(bob, 300.0);

    alice.print();
    bob.print();
    ret;
}

@pure
fn isLeapYear(year: Int) -> Bool {
    if year % 400 == 0 { ret true; }
    if year % 100 == 0 { ret false; }
    if year % 4 == 0 { ret true; }
    ret false;
}

@pure
fn daysInMonth(year: Int, month: Int) -> Int {
    if month == 2 { if isLeapYear(year) { ret 29; } ret 28; }
    if month == 4 || month == 6 || month == 9 || month == 11 { ret 30; }
    ret 31;
}

@pure
fn dayOfYear(year: Int, month: Int, day: Int) -> Int {
    let total: Int = 0;
    loop m in 1..month + 1 {
        if m < month {
            total = total + daysInMonth(year, m);
        } else {
            total = total + day;
        }
    }
    ret total;
}

@pure
fn addDays(year: Int, month: Int, day: Int, days: Int) -> Text {
    let d: Int = day + days;
    let m: Int = month;
    let y: Int = year;
    loop d > daysInMonth(y, m) {
        d = d - daysInMonth(y, m);
        m = m + 1;
        if m > 12 { m = 1; y = y + 1; }
    }
    ret int_to_text(y) + "-" + int_to_text(m) + "-" + int_to_text(d);
}

fn main() -> Void {
    let year: Int = 2024;
    let month: Int = 3;
    let day: Int = 15;

    fx {
        println("Date: ", year, "-", month, "-", day);
        println("Day of year: ", dayOfYear(year, month, day));
        println("100 days later: ", addDays(year, month, day, 100));
        println("Is 2024 leap? ", isLeapYear(2024));
    }
    ret;
}

type HashEntry {
    key: Text;
    value: Text;
    next: HashEntry;
}

fn makeHashEntry(k: Text, v: Text) -> HashEntry {
    ret new HashEntry { key: k, value: v, next: nil };
}

type HashMap {
    buckets: HashEntry[];
    capacity: Int;

    fn hash(key: Text) -> Int {
        let h: Int = 0;
        let len: Int = string_len(key);
        loop i in 0..len { h = h * 31 + ord(key[i..i + 1]); }
        if h < 0 { h = -h; }
        ret h % self.capacity;
    }

    fn put(key: Text, value: Text) -> Void {
        let idx: Int = self.hash(key);
        let entry: HashEntry = self.buckets[idx];
        loop entry != nil {
            if entry.key == key { entry.value = value; ret; }
            entry = entry.next;
        }
        let newEntry: HashEntry = makeHashEntry(key, value);
        newEntry.next = self.buckets[idx];
        self.buckets[idx] = newEntry;
        ret;
    }

    fn get(key: Text) -> Text {
        let idx: Int = self.hash(key);
        let entry: HashEntry = self.buckets[idx];
        loop entry != nil { if entry.key == key { ret entry.value; } entry = entry.next; }
        ret "";
    }

    fn contains(key: Text) -> Bool {
        ret self.get(key) != "";
    }
}

fn makeHashMap(cap: Int) -> HashMap {
    let buckets: HashEntry[] = [];
    loop i in 0..cap { buckets = buckets + [nil]; }
    ret new HashMap { buckets: buckets, capacity: cap };
}

fn main() -> Void {
    let map: HashMap = makeHashMap(16);

    map.put("name", "Alice");
    map.put("city", "Wonderland");
    map.put("age", "30");

    fx {
        println("name: ", map.get("name"));
        println("city: ", map.get("city"));
        println("contains 'age'? ", map.contains("age"));
        println("contains 'email'? ", map.contains("email"));
    }
    ret;
}

type TreeNode {
    value: Int;
    left: TreeNode;
    right: TreeNode;
}

fn makeTreeNode(val: Int) -> TreeNode {
    ret new TreeNode { value: val, left: nil, right: nil };
}

fn insert(root: TreeNode, val: Int) -> TreeNode {
    if root == nil { ret makeTreeNode(val); }
    if val < root.value {
        root.left = insert(root.left, val);
    } else {
        root.right = insert(root.right, val);
    }
    ret root;
}

fn inorder(root: TreeNode) -> Text {
    if root == nil { ret ""; }
    let result: Text = inorder(root.left);
    result = result + int_to_text(root.value) + " ";
    result = result + inorder(root.right);
    ret result;
}

fn preorder(root: TreeNode) -> Text {
    if root == nil { ret ""; }
    let result: Text = int_to_text(root.value) + " ";
    result = result + preorder(root.left);
    result = result + preorder(root.right);
    ret result;
}

fn postorder(root: TreeNode) -> Text {
    if root == nil { ret ""; }
    let result: Text = postorder(root.left);
    result = result + postorder(root.right);
    result = result + int_to_text(root.value) + " ";
    ret result;
}

fn main() -> Void {
    let root: TreeNode = nil;
    root = insert(root, 50);
    root = insert(root, 30);
    root = insert(root, 70);
    root = insert(root, 20);
    root = insert(root, 40);
    root = insert(root, 60);
    root = insert(root, 80);

    fx {
        println("Inorder:   ", inorder(root));
        println("Preorder:  ", preorder(root));
        println("Postorder: ", postorder(root));
    }
    ret;
}

@pure
fn is_prime(n: Int) -> Bool {
    if n <= 1 { ret false; }
    if n == 2 { ret true; }
    if n % 2 == 0 { ret false; }
    let max: Int = int(sqrt(real(n)));
    let i: Int = 3;
    loop i <= max { if n % i == 0 { ret false; } i = i + 2; }
    ret true;
}

fn generate_primes(limit: Int) -> Int[] {
    let primes: Int[] = [];
    loop i in 2..limit { if is_prime(i) { primes = primes + [i]; } }
    ret primes;
}

