fn split_csv_line(line: Text) -> Text[] {
    let parts: Text[] = [];
    let current: Text = "";
    let i: Int = 0;
    loop i < string_len(line) {
        let ch: Text = line[i..i + 1];
        if ch == "," {
            parts = parts + [current];
            current = "";
        } else {
            current = current + ch;
        }
        i = i + 1;
    }
    parts = parts + [current];
    ret parts;
