            }
        }
    }
    ret;
}

@pure
fn bfs8(walls: Int[], start: Int, goal: Int) -> Int {
    // 64 cells; row = idx >> 3, col = idx & 7
    let dist: Int[] = [];
    loop i in 0..64 { dist = dist + [-1]; }
    let queue: Int[] = [];
    queue = queue + [start];
    dist[start] = 0;
    let head: Int = 0;
    loop guard in 0..64 {
        if head < length(queue) {
            let cur: Int = queue[head];
            head = head + 1;
            let row: Int = cur >> 3;
            let col: Int = cur & 7;
            let next: Int = dist[cur] + 1;
            if row > 0 {
                let nb: Int = cur - 8;
                if walls[nb] == 0 && dist[nb] == -1 {
                    dist[nb] = next;
                    queue = queue + [nb];
                }
            }
            if row < 7 {
                let nb: Int = cur + 8;
                if walls[nb] == 0 && dist[nb] == -1 {
                    dist[nb] = next;
                    queue = queue + [nb];
                }
            }
            if col > 0 {
                let nb: Int = cur - 1;
                if walls[nb] == 0 && dist[nb] == -1 {
                    dist[nb] = next;
                    queue = queue + [nb];
                }
            }
            if col < 7 {
                let nb: Int = cur + 1;
                if walls[nb] == 0 && dist[nb] == -1 {
                    dist[nb] = next;
                    queue = queue + [nb];
                }
            }
        }
    }
    ret dist[goal];
}

fn main() -> Void {
    let walls: Int[] = [];
    loop i in 0..64 { walls = walls + [0]; }
    // vertical barrier in column 4, rows 0..6, with a gap at row 7
    loop r in 0..7 { walls[r * 8 + 4] = 1; }
    // extra rubble
    walls[9] = 1;
    walls[10] = 1;
    walls[11] = 1;
    walls[50] = 1;
    walls[51] = 1;

    let d: Int = bfs8(walls, 0, 63);

    fx {
        loop r in 0..8 {
            let line: Text = "";
            loop c in 0..8 {
                if walls[r * 8 + c] == 1 {
                    line = line + "#";
                } else {
                    line = line + ".";
                }
            }
            println(line);
        }
        println("shortest path (0,0) -> (7,7) = ", d);
    }
    ret;
}

fn main() -> Void {
    let c3: Int = 0;
    let c5: Int = 0;
    fx {
        loop n in 1..31 {
            c3 = c3 + 1;
            c5 = c5 + 1;
            let label: Text = "";
            if c3 == 3 { label = label + "Fizz"; c3 = 0; }
            if c5 == 5 { label = label + "Buzz"; c5 = 0; }
            if label == "" {
                println(n);
            } else {
                println(label);
            }
        }
    }
    ret;
}

@pure
fn fibTable(count: Int) -> Int[] {
    let xs: Int[] = [0, 1];
    loop i in 2..count { xs = xs + [xs[i - 2] + xs[i - 1]]; }
    ret xs;
}

fn main() -> Void {
    let fibs: Int[] = fibTable(15);
    fx {
        loop i in 0..length(fibs) { println("fib(", i, ") = ", fibs[i]); }
        loop i in 2..length(fibs) {
            let ratio: Real = (fibs[i] * 1.0) / fibs[i - 1];
            println("ratio ", i, " = ", ratio:0:6);
        }
    }
    ret;
}

@pure
fn gcd(a: Int, b: Int) -> Int {
    if a == b { ret a; }
    if a > b { ret gcd(a - b, b); }
    ret gcd(a, b - a);
}

@pure
fn exactDivide(n: Int, d: Int) -> Int {
    let limit: Int = n + 1;
    loop i in 1..limit { if i * d == n { ret i; } if i * d > n { ret 0; } }
    ret 0;
}

@pure
fn lcm(a: Int, b: Int) -> Int {
    let g: Int = gcd(a, b);
    ret a * exactDivide(b, g);
}

fn main() -> Void {
    fx {
        println("gcd of 48 and 18 -> ", gcd(48, 18));
        println("gcd of 1071 and 462 -> ", gcd(1071, 462));
        println("lcm of 21 and 6 -> ", lcm(21, 6));
        println("lcm of 7 and 13 -> ", lcm(7, 13));
    }
    ret;
}

// Recaman's sequence (OEIS A005132): a(n) = a(n-1) - n when that value is
// positive and not yet in the sequence, otherwise a(n) = a(n-1) + n.
// The addition branch may repeat earlier values. Whether EVERY nonnegative
// integer eventually appears is still an open problem.

fn main() -> Void {
    let terms: Int = 201;            // compute a(0) .. a(200)
    let seq: Int[] = [0];
    let seen: Bool[] = [true];       // seen[v] <=> v already in sequence
    let current: Int = 0;

    loop step in 1..terms {
        let back: Int = current - step;
        if back > 0 { loop length(seen) <= back { seen = seen + [false]; } }
        if back > 0 && !seen[back] {
            current = back;
        } else {
            current = current + step;
        }
        loop length(seen) <= current { seen = seen + [false]; }
        seen[current] = true;
        seq = seq + [current];
    }

    fx {
        println("Recaman's sequence, a(0) .. a(59):");
        loop i in 0..60 { print(seq[i], " "); }
        println("");
        println("");
    }

    // Hunt for the small values inside the computed window.
    loop k in 0..16 {
        let at: Int = -1;
        let i: Int = 0;
        loop i < length(seq) { if seq[i] == k { at = i; break; } i = i + 1; }
        fx {
            if at >= 0 {
                println(k, " first appears at index ", at);
            } else {
                println(k, " does not appear in the first ", length(seq), " terms");
            }
        }
    }
    ret;
}

@pre n > 1
@pure
fn isPrimeTrial(n: Int) -> Bool {
    if n % 2 == 0 {
        ret n == 2;
    }
    let d: Int = 3;
    loop d * d <= n {
        if n % d == 0 {
            ret false;
        }
        d = d + 2;
    }
    ret true;
}

// P(n) mod n, computed iteratively so values never explode.
@pre n > 0
@pure
fn perrinMod(n: Int) -> Int {
    if n == 1 {
        ret 0;                 // P(1) = 0
    }
    if n == 2 {
        ret 0;                 // P(2) = 2 == 0 (mod 2)
    }
    let a: Int = 3 % n;        // P(0)
    let b: Int = 0;            // P(1)
    let c: Int = 2 % n;        // P(2)
    let k: Int = 3;
    loop k <= n {
        let next: Int = (a + b) % n;
        a = b;
        b = c;
        c = next;
        k = k + 1;
    }
    ret c;
}

fn report(n: Int) -> Void {
    let prime: Bool = isPrimeTrial(n);
    let passes: Bool = perrinMod(n) == 0;
    fx {
        print(n, ": ");
        if prime {
            print("prime,     ");
        } else {
            print("composite, ");
        }
        if passes {
            print("PASSES Perrin test");
        } else {
            print("fails Perrin test");
        }
        if !prime && passes {
            print("   <-- Perrin pseudoprime!");
        }
        println("");
    }
    ret;
}

fn main() -> Void {
    let candidates: Int[] = [7, 521, 561, 271441, 904631];
    loop i in 0..length(candidates) {
        report(candidates[i]);
    }
    fx {
        println("(561 is a Carmichael number: it fools Fermat, but not Perrin)");
    }
    ret;
}

@pre n > 0
@pure
fn properDivisors(n: Int) -> Int[] {
    let ds: Int[] = [];
    if n > 1 { ds = ds + [1]; }
    let d: Int = 2;
    loop d * d <= n {
        if n % d == 0 {
            ds = ds + [d];
            let other: Int = n / d;
            if other != d { ds = ds + [other]; }
        }
        d = d + 1;
    }
    ret ds;
}

@pure
fn sumOf(xs: Int[]) -> Int {
    let total: Int = 0;
    loop i in 0..length(xs) { total = total + xs[i]; }
    ret total;
}

// Subset-sum over the divisor list: classic boolean DP, scanning sums
// downward so each divisor is used at most once.
@pure
fn subsetSumsTo(ds: Int[], target: Int) -> Bool {
    let can: Bool[] = [true];        // sum 0 is always reachable
    loop i in 0..target { can = can + [false]; }
    loop di in 0..length(ds) {
        let d: Int = ds[di];
        let s: Int = target;
        loop s >= d { if !can[s] && can[s - d] { can[s] = true; } s = s - 1; }
    }
    ret can[target];
}

@pre n > 0
@pure
fn isWeird(n: Int) -> Bool {
    let ds: Int[] = properDivisors(n);
    if sumOf(ds) <= n {
        ret false;                   // deficient or perfect: disqualified
    }
    ret !subsetSumsTo(ds, n);
}

fn main() -> Void {
    fx { println("weird numbers below 1000:"); }
    loop n in 1..1000 {
        if isWeird(n) {
            let ds: Int[] = properDivisors(n);
            fx {
                println(n, ": divisors sum to ", sumOf(ds), ", yet no subset adds up to ", n);
            }
        }
    }
    ret;
}

// Van Eck's sequence (OEIS A181391): a(0) = 0. For n > 0, look at a(n-1).
// If that value occurred earlier in the sequence, a(n) is the distance
// back to its MOST RECENT prior occurrence; otherwise a(n) = 0.
// Whether every nonnegative integer eventually appears is open.

fn main() -> Void {
    let terms: Int = 30;
    let seq: Int[] = [0];
    let lastSeen: Int[] = [-1];   // lastSeen[v] = most recent index of v, or -1

    let i: Int = 1;
    loop i < terms {
        let prev: Int = seq[i - 1];
        loop length(lastSeen) <= prev { lastSeen = lastSeen + [-1]; }
        let j: Int = lastSeen[prev];
        let next: Int = 0;
        if j >= 0 { next = (i - 1) - j; }
        lastSeen[prev] = i - 1;
        seq = seq + [next];
        i = i + 1;
    }

    fx {
        println("Van Eck's sequence, a(0) .. a(", terms - 1, "):");
        loop k in 0..terms { print(seq[k], " "); }
        println("");
    }
    ret;
}

// Multiplicative persistence: repeatedly multiply a number's digits until
// a single digit remains; count the steps. Erdos conjectured that no
// base-10 number needs more than 11 steps. It remains unproven -- only
// checked far beyond any number yet found. This scan hunts for the
// "record holder" (the largest persistence reached) below a range.

@pure
fn digitProduct(n: Int) -> Int {
    let value: Int = n;
    let product: Int = 1;
    if value == 0 { ret 0; }
    loop value > 0 { product = product * (value % 10); value = value / 10; }
    ret product;
}

@pre n >= 0
@pure
fn persistence(n: Int) -> Int {
    let value: Int = n;
    let steps: Int = 0;
    loop value >= 10 { value = digitProduct(value); steps = steps + 1; }
    ret steps;
}

fn main() -> Void {
    let rangeMax: Int = 100000;
    let champion: Int = 0;
    let best: Int = 0;
    loop n in 0..rangeMax {
        let p: Int = persistence(n);
        if p > best { best = p; champion = n; }
    }

    fx {
        println("multiplicative persistence scan, n = 0..", rangeMax - 1);
        println("champion: ", champion, " with persistence ", best);
        println("(no base-10 number is known to need more than 11 steps -- still unproven)");
    }
    ret;
}

// Aliquot sequence: a(0) = seed, a(k+1) = sum of proper divisors of a(k).
// Outcomes: hits 0 (terminates), hits a fixed point (perfect number),
// falls into a cycle (amicable/sociable numbers), or -- for a handful of
// small seeds including 276, 552, 564, 660, 966 (the "Lehmer five") --
// nobody knows. Whether these always resolve is the open Catalan-Dickson
// conjecture. Each seed races independently via par (PAR-001): every
// branch gets its own out-record to write into.

type ScanResult {
    seed: Int;
    status: Int;      // 0=hit 0, 1=perfect fixed point, 2=cycle, 3=unresolved
    steps: Int;
    finalValue: Int;
    peakValue: Int;
}

@pre n >= 0
@pure
fn aliquotSum(n: Int) -> Int {
    if n <= 1 { ret 0; }
    let total: Int = 1;
    let d: Int = 2;
    loop d * d <= n {
        if n % d == 0 {
            total = total + d;
            let other: Int = n / d;
            if other != d { total = total + other; }
        }
        d = d + 1;
    }
    ret total;
}

fn traceAliquot(out: ScanResult, seed: Int, stepCap: Int) -> Void {
    let history: Int[] = [seed];
    let current: Int = seed;
    let peak: Int = seed;
    let step: Int = 0;
    let status: Int = 3;
    let finalValue: Int = seed;

    loop step < stepCap {
        let next: Int = aliquotSum(current);
        step = step + 1;

        if next == 0 {
            status = 0;
            finalValue = 0;
            break;
        }
        if next == current {
            status = 1;
            finalValue = next;
            break;
        }

        let seenAt: Int = -1;
        loop i in 0..length(history) { if history[i] == next { seenAt = i; break; } }
        if seenAt >= 0 {
            status = 2;
            finalValue = next;
            break;
        }

        if next > peak { peak = next; }
        history = history + [next];
        current = next;
        finalValue = current;
    }

    out.seed = seed;
    out.status = status;
    out.steps = step;
    out.finalValue = finalValue;
    out.peakValue = peak;
    ret;
}

fn describe(r: ScanResult) -> Void {
    fx {
        print("seed ", r.seed, ": ");
        if r.status == 0 {
            println("terminates at 0 after ", r.steps, " steps (peak ", r.peakValue, ")");
        } else {
            if r.status == 1 {
                println("reaches perfect-number fixed point ", r.finalValue, " after ", r.steps, " steps");
            } else {
                if r.status == 2 {
                    println("falls into a cycle at ", r.finalValue, " after ", r.steps, " steps");
                } else {
                    println("UNRESOLVED after ", r.steps, " steps (peak so far ", r.peakValue, ") -- fate unknown");
                }
            }
        }
    }
    ret;
}

fn main() -> Void {
    let capSteps: Int = 40;

    let rPerfect: ScanResult = new ScanResult();
    let rAmicable: ScanResult = new ScanResult();
    let rDeficient: ScanResult = new ScanResult();
    let rLehmer276: ScanResult = new ScanResult();
    let rLehmer552: ScanResult = new ScanResult();

    par {
        traceAliquot(rPerfect, 6, capSteps);
        traceAliquot(rAmicable, 220, capSteps);
        traceAliquot(rDeficient, 95, capSteps);
        traceAliquot(rLehmer276, 276, capSteps);
        traceAliquot(rLehmer552, 552, capSteps);
    }

    describe(rPerfect);
    describe(rAmicable);
    describe(rDeficient);
    describe(rLehmer276);
    describe(rLehmer552);

    fx {
        println("");
        println("276, 552, 564, 660, and 966 are the 'Lehmer five': the smallest seeds");
        println("whose aliquot sequence fate is still unknown -- the Catalan-Dickson conjecture.");
    }
    ret;
}

// A number n is a "self number" (Colombian number) if there is no m with
// g(m) = m + digitSum(m) equal to n. Sieve every generator up to the
// limit, mark what it produces, and whatever's left unmarked is self.

@pure
fn digitSum(n: Int) -> Int {
    let value: Int = n;
    let total: Int = 0;
    loop value > 0 { total = total + (value % 10); value = value / 10; }
    ret total;
}

@pre limit > 0
@pure
fn selfNumberSieve(limit: Int) -> Bool[] {
    let generated: Bool[] = [];
    loop i in 0..(limit + 1) { generated = generated + [false]; }
    loop m in 1..(limit + 1) {
        let g: Int = m + digitSum(m);
        if g <= limit { generated[g] = true; }
    }
    ret generated;
}

@pre n > 1
@pure
fn isPrimeTrial(n: Int) -> Bool {
    if n % 2 == 0 { ret n == 2; }
    let d: Int = 3;
    loop d * d <= n { if n % d == 0 { ret false; } d = d + 2; }
    ret true;
}

fn main() -> Void {
    let limit: Int = 150;
    let generated: Bool[] = selfNumberSieve(limit);

    fx { println("self numbers (Colombian numbers) up to ", limit, ":"); }
    loop n in 1..(limit + 1) {
        if !generated[n] {
            let star: Bool = n > 1 && isPrimeTrial(n);
            fx {
                if star {
                    println(n, "  <-- also prime (a self prime)");
                } else {
                    println(n);
                }
            }
        }
    }
    ret;
}

// Somos-4 (OEIS A006720): a(1..4) = 1, and for n > 4,
//   a(n) = (a(n-1)*a(n-3) + a(n-2)^2) / a(n-4)
// Every term is an integer despite the division at every step -- the
// "Laurent phenomenon," proved by Fomin and Zelevinsky in 2002. This
// walk logs every step into an MStream (written one byte per character
// via mstream_write_byte) and flushes it once at the end.

fn appendText(ms: MStream, text: Text) -> Void {
    let n: Int = length(text);
    loop i in 0..n { let ch: Text = text[i..i + 1]; mstream_write_byte(ms, ord(ch)); }
    ret;
}

fn main() -> Void {
    let terms: Int = 13;
    let a: Int[] = [1, 1, 1, 1];
    let log: MStream = mstream_new();

    appendText(log, "Somos-4 sequence trace\n");
    appendText(log, "n=1..4: 1, 1, 1, 1 (seeds)\n");

    let n: Int = 5;
    loop n <= terms {
        let numerator: Int = a[n - 2] * a[n - 4] + a[n - 3] * a[n - 3];
        let denom: Int = a[n - 5];
        let remainder: Int = numerator % denom;

        if remainder != 0 {
            fx {
                println("UNEXPECTED: non-exact division at n=", n, " -- a counterexample to Laurent!");
            }
        }

        let next: Int = numerator / denom;
        a = a + [next];

        appendText(log, "n=" + int_to_text(n) + ": -> " + int_to_text(next) + "\n");

        n = n + 1;
    }

    let report: Text = mstream_text(log);
    fx {
        print(report);
        println("");
        println("Every division above came out exact -- the Laurent phenomenon holds.");
    }

    mstream_free(log);
    ret;
}

// Ulam numbers (OEIS A002858): u(1)=1, u(2)=2. Each subsequent term is
// the smallest integer greater than the previous term that can be
// written as the sum of two DISTINCT earlier terms in EXACTLY ONE way.
// No formula is known, and whether lim u(n)/n exists is an open problem.

@pure
fn countRepresentations(ulam: Int[], m: Int) -> Int {
    let count: Int = 0;
    let k: Int = length(ulam);
    let i: Int = 0;
    loop i < k {
        let j: Int = i + 1;
        loop j < k {
            let s: Int = ulam[i] + ulam[j];
            if s == m {
                count = count + 1;
            }
            if s > m {
                break;          // sums grow with j since ulam is sorted
            }
            j = j + 1;
        }
        i = i + 1;
    }
    ret count;
}

fn main() -> Void {
    let ulam: Int[] = [1, 2];
    let wanted: Int = 20;

    loop length(ulam) < wanted {
        let last: Int = ulam[length(ulam) - 1];
        let candidate: Int = last + 1;
        let found: Bool = false;
        loop !found {
            if countRepresentations(ulam, candidate) == 1 {
                ulam = ulam + [candidate];
                found = true;
            } else {
                candidate = candidate + 1;
            }
        }
    }

    fx {
        println("Ulam numbers, u(1)..u(20):");
        loop i in 0..length(ulam) {
            print(ulam[i], " ");
        }
        println("");
        println("No formula is known; even the existence of lim u(n)/n is unproven.");
    }
    ret;
}

// Munchausen numbers: n such that sum(d^d for each digit d) == n,
// using the convention 0^0 := 0. Named because the number "lifts
// itself" the way Baron Munchausen claimed to pull himself out of a
// swamp by his own hair. In base 10 there are only FOUR known:
// 0, 1, 3435, and 438579088 -- and it's proven no others exist below
// a very large bound via a digit-sum argument, though this scan only
// checks a small window.

@pure
fn digitPower(d: Int) -> Int {
    if d == 0 { ret 0; }
    let result: Int = 1;
    let i: Int = 0;
    loop i < d { result = result * d; i = i + 1; }
    ret result;
}

@pre n > 0
@pure
fn munchausenSum(n: Int) -> Int {
    let value: Int = n;
    let total: Int = 0;
    loop value > 0 { total = total + digitPower(value % 10); value = value / 10; }
    ret total;
}

fn main() -> Void {
    let limit: Int = 5000;
    fx { println("Munchausen numbers up to ", limit, ":"); }
    loop n in 1..(limit + 1) { if munchausenSum(n) == n { fx { println(n); } } }
    fx { println(""); println("The only other known Munchausen number is 438579088."); }
    ret;
}

// Kolakoski sequence (OEIS A000002): the only sequence over {1,2} that
// is its own run-length encoding. Seed with [1,2,2], then read the
// sequence's own earlier entries as instructions for how many times to
// repeat the next alternating value. Whether 1s and 2s each occur with
// limiting density exactly 1/2 remains an open conjecture.

fn main() -> Void {
    let n: Int = 30;
    let seq: Int[] = [1, 2, 2];
    let i: Int = 2;

    loop length(seq) < n {
        let last: Int = seq[length(seq) - 1];
        let nextVal: Int = 1;
        if last == 1 { nextVal = 2; }
        let runLength: Int = seq[i];
        let r: Int = 0;
        loop r < runLength { seq = seq + [nextVal]; r = r + 1; }
        i = i + 1;
    }

    fx {
        println("Kolakoski sequence, a(1)..a(", n, "):");
        loop k in 0..n { print(seq[k], " "); }
        println("");
        println("Conjectured -- unproven -- that both digits occur with density 1/2.");
    }
    ret;
}

// Erdos-Straus conjecture: for every integer n >= 2, 4/n = 1/x + 1/y + 1/z
// has a solution in positive integers. Proven for several residue
// classes mod small numbers (e.g. n = 3 mod 4, via the identity
// 1/k = 1/(k+1) + 1/(k(k+1))) but open in general. Each n races
// independently via par (PAR-001); the search is bounded, so a
// "not found" result is a search-limit failure, not a disproof.

type FractionSearch {
    n: Int;
    found: Bool;
    x: Int;
    y: Int;
    z: Int;
}

fn searchErdosStraus(out: FractionSearch, n: Int, xBound: Int, yBound: Int) -> Void {
    let x: Int = n / 4 + 1;
    let resultFound: Bool = false;
    let resultX: Int = 0;
    let resultY: Int = 0;
    let resultZ: Int = 0;
    loop x <= xBound {
        if !resultFound {
            let num1: Int = 4 * x - n;
            if num1 > 0 {
                let den1: Int = n * x;
                let y: Int = x;
                loop y <= yBound {
                    if !resultFound {
                        let denomZ: Int = num1 * y - den1;
                        if denomZ > 0 {
                            let numerZ: Int = den1 * y;
                            if numerZ % denomZ == 0 {
                                let z: Int = numerZ / denomZ;
                                if z > 0 {
                                    resultFound = true;
                                    resultX = x;
                                    resultY = y;
                                    resultZ = z;
                                }
                            }
                        }
                    }
                    y = y + 1;
                }
            }
        }
        x = x + 1;
    }
    out.n = n;
    out.found = resultFound;
    out.x = resultX;
    out.y = resultY;
    out.z = resultZ;
    ret;
}

fn describe(r: FractionSearch) -> Void {
    fx {
        if r.found {
            println("n=", r.n, ": 4/", r.n, " = 1/", r.x, " + 1/", r.y, " + 1/", r.z);
        } else {
            println("n=", r.n, ": no solution within bounds (not a disproof)");
        }
    }
    ret;
}

fn main() -> Void {
    let xBound: Int = 200;
    let yBound: Int = 20000;

    let r5: FractionSearch = new FractionSearch();
    let r7: FractionSearch = new FractionSearch();
    let r11: FractionSearch = new FractionSearch();
    let r13: FractionSearch = new FractionSearch();
    let r19: FractionSearch = new FractionSearch();

    par {
        searchErdosStraus(r5, 5, xBound, yBound);
        searchErdosStraus(r7, 7, xBound, yBound);
        searchErdosStraus(r11, 11, xBound, yBound);
        searchErdosStraus(r13, 13, xBound, yBound);
        searchErdosStraus(r19, 19, xBound, yBound);
    }

    describe(r5);
    describe(r7);
    describe(r11);
    describe(r13);
    describe(r19);

    fx {
        println("");
        println("Verified by computer search for enormous n; a general proof or");
        println("counterexample is still unknown.");
    }
    ret;
}

// Dudeney numbers: n such that digitSum(n)^3 == n. Named for Henry
// Dudeney, the puzzle-maker. Unlike the last four examples, this one
// is fully resolved: exactly seven exist (including the two trivial
// cases 0 and 1), and it's an easy pigeonhole argument to show no
// others can exist beyond a small bound -- digit sums grow far slower
// than cubes.

@pure
fn digitSum(n: Int) -> Int {
    let value: Int = n;
    let total: Int = 0;
    loop value > 0 { total = total + (value % 10); value = value / 10; }
    ret total;
}

@pre n >= 0
@pure
fn cube(n: Int) -> Int {
    ret n * n * n;
}

fn main() -> Void {
    let limit: Int = 20000;
    fx { println("Dudeney numbers up to ", limit, ":"); }
    loop n in 0..(limit + 1) {
        if cube(digitSum(n)) == n {
            fx { println(n, "  (digit sum ", digitSum(n), ", cubed)"); }
        }
    }
    ret;
}

// American Soundex: keep the first letter, then map remaining letters to
// digits (b,f,p,v=1; c,g,j,k,q,s,x,z=2; d,t=3; l=4; m,n=5; r=6), collapsing
// adjacent letters with the same digit into one. Vowels always break a run
// of identical digits. H and W are the famous edge case: the official NARA
// rule treats them as "transparent" (they don't break a run), but many
// implementations wrongly treat them like vowels -- producing two different,
// both "standard," codes for the same name.

@pure
fn soundexDigit(c: Int) -> Int {
    if c == 66 || c == 70 || c == 80 || c == 86 { ret 1; }              // B F P V
    if c == 67 || c == 71 || c == 74 || c == 75 || c == 81 || c == 83 || c == 88 || c == 90 { ret 2; } // C G J K Q S X Z
    if c == 68 || c == 84 { ret 3; }   // D T
    if c == 76 { ret 4; }              // L
    if c == 77 || c == 78 { ret 5; }   // M N
    if c == 82 { ret 6; }              // R
    ret 0;                              // vowels, Y -- and H/W, handled separately
}

@pure
fn isHOrW(c: Int) -> Bool {
    ret c == 72 || c == 87;
}

@pre length(name) > 0
fn soundex(name: Text, hwAreSeparators: Bool) -> Text {
    let upper: Int[] = [];
    loop i in 0..length(name) {
        let ch: Text = name[i..i + 1];
        let c: Int = ord(ch);
        if c >= 97 && c <= 122 { c = c - 32; }
        upper = upper + [c];
    }

    let digits: Text = "";
    let lastDigit: Int = soundexDigit(upper[0]);

    let j: Int = 1;
    loop j < length(upper) && length(digits) < 3 {
        let c: Int = upper[j];
        if isHOrW(c) {
            if hwAreSeparators { lastDigit = 0; }
            // else: transparent -- lastDigit unchanged, per the NARA rule
        } else {
            let d: Int = soundexDigit(c);
            if d == 0 {
                lastDigit = 0;   // a true vowel always breaks the run
            } else {
                if d != lastDigit { digits = digits + int_to_text(d); }
                lastDigit = d;
            }
        }
        j = j + 1;
    }

    loop length(digits) < 3 { digits = digits + "0"; }

    ret chr(upper[0]) + digits;
}

fn main() -> Void {
    fx {
        println("Soundex, transparent-H/W vs. H/W-as-separator conventions:");
        println("Robert   -> ", soundex("Robert", false), " / ", soundex("Robert", true));
        println("Rupert   -> ", soundex("Rupert", false), " / ", soundex("Rupert", true));
        println("Ashcraft -> ", soundex("Ashcraft", false), " / ", soundex("Ashcraft", true));
        println("Tymczak  -> ", soundex("Tymczak", false), " / ", soundex("Tymczak", true));
    }
    ret;
}

// Word ladder: given a dictionary and a start/end word of equal length,
// find the shortest chain where each step changes exactly one letter and
// every intermediate word is itself a valid dictionary word. This is
// graph BFS where the graph is never built explicitly -- edges are
// computed on the fly from letter-by-letter comparison.

type LadderResult {
    found: Bool;
    length: Int;
    path: Int[];
}

@pure
fn oneLetterApart(a: Text, b: Text) -> Bool {
    if length(a) != length(b) { ret false; }
    let diff: Int = 0;
    loop i in 0..length(a) {
        if ord(a[i..i + 1]) != ord(b[i..i + 1]) { diff = diff + 1; }
    }
    ret diff == 1;
}

fn wordLadderBFS(nodes: Text[], startIdx: Int, endIdx: Int) -> LadderResult {
    let n: Int = length(nodes);
    let dist: Int[] = [];
    let parent: Int[] = [];
    loop i in 0..n { dist = dist + [-1]; parent = parent + [-1]; }

    dist[startIdx] = 1;
    let queue: Int[] = [];
    queue = queue + [startIdx];
    let head: Int = 0;

    loop head < length(queue) {
        let current: Int = queue[head];
        head = head + 1;
        if current == endIdx { break; }
        loop j in 0..n {
            if dist[j] == -1 && oneLetterApart(nodes[current], nodes[j]) {
                dist[j] = dist[current] + 1;
                parent[j] = current;
                queue = queue + [j];
            }
        }
    }

    if dist[endIdx] == -1 { ret LadderResult { found: false, length: 0, path: [] }; }

    let reversePath: Int[] = [];
    let walker: Int = endIdx;
    loop walker != -1 { reversePath = reversePath + [walker]; walker = parent[walker]; }

    let path: Int[] = [];
    let k: Int = length(reversePath) - 1;
    loop k >= 0 { path = path + [reversePath[k]]; k = k - 1; }

    ret LadderResult { found: true, length: dist[endIdx], path: path };
}

fn main() -> Void {
    let nodes: Text[] = ["hit", "hot", "dot", "dog", "lot", "log", "cog"];
    let result: LadderResult = wordLadderBFS(nodes, 0, 6);

    fx {
        if result.found {
            print("Shortest ladder (length ", result.length, "): ");
            loop i in 0..length(result.path) {
                print(nodes[result.path[i]]);
                if i < length(result.path) - 1 { print(" -> "); }
            }
            println("");
        } else {
            println("No ladder exists with this dictionary.");
        }
    }
    ret;
}

// A semordnilap is a word whose reversal is itself a different valid word
// (as opposed to a palindrome, whose reversal is ITSELF). Named by reversing
// the word "palindromes" -- which is not actually a semordnilap of anything,
// making the term a little joke about itself.

@pure
fn reverseWord(w: Text) -> Text {
    let result: Text = "";
    let i: Int = length(w) - 1;
    loop i >= 0 { result = result + w[i..i + 1]; i = i - 1; }
    ret result;
}

@pure
fn containsWord(list: Text[], target: Text) -> Bool {
    loop i in 0..length(list) { if list[i] == target { ret true; } }
    ret false;
}

fn main() -> Void {
    let words: Text[] = ["stressed", "desserts", "drawer", "reward", "diaper",
                          "repaid", "deified", "level", "dog", "god", "straw",
                          "warts", "lager", "regal", "bard", "drab"];

    fx { println("Semordnilaps found:"); }
    let reportedPairs: Text[] = [];
    loop i in 0..length(words) {
        let w: Text = words[i];
        let rev: Text = reverseWord(w);
        if rev != w && containsWord(words, rev) {
            let pairKey: Text = w;
            if rev < w { pairKey = rev; }
            if !containsWord(reportedPairs, pairKey) {
                reportedPairs = reportedPairs + [pairKey];
                fx { println(w, " <-> ", rev); }
            }
        }
    }
    ret;
}

// Zipf's Law: in natural-language text, word frequency is roughly
// inversely proportional to rank -- the 2nd most common word appears
// about half as often as the most common, the 3rd about a third as
// often, etc., so rank*frequency is roughly constant. Oddly, Miller's
// "monkey-typing" model shows even RANDOMLY generated text obeys a
// Zipf-like law -- so whether the pattern reveals anything deep about
// language, or is just a near-inevitable statistical artifact, is a
// genuinely unsettled linguistics debate.

fn main() -> Void {
    let text: Text[] = [
        "the", "quick", "fox", "runs", "and", "the", "dog", "sits", "and", "the",
        "cat", "watches", "the", "quick", "fox", "and", "the", "dog", "the", "cat",
        "and", "the", "fox", "the", "dog", "watches", "and", "the", "quick", "cat",
        "runs", "and", "sits", "the", "fox", "the", "dog", "the", "cat", "and"
    ];

    let uniqueWords: Text[] = [];
    let counts: Int[] = [];

    loop i in 0..length(text) {
        let w: Text = text[i];
        let idx: Int = -1;
        loop j in 0..length(uniqueWords) { if uniqueWords[j] == w { idx = j; break; } }
        if idx == -1 {
            uniqueWords = uniqueWords + [w];
            counts = counts + [1];
        } else {
            counts[idx] = counts[idx] + 1;
        }
    }

    let n: Int = length(uniqueWords);
    loop pass in 0..n {
        loop k in 0..(n - 1) {
            if counts[k] < counts[k + 1] {
                let tempCount: Int = counts[k];
                counts[k] = counts[k + 1];
                counts[k + 1] = tempCount;
                let tempWord: Text = uniqueWords[k];
                uniqueWords[k] = uniqueWords[k + 1];
                uniqueWords[k + 1] = tempWord;
            }
        }
    }

    fx {
        println("Zipf's Law check on a short sample text:");
        println("rank  word       freq   rank*freq");
        loop r in 0..n {
            println(r + 1, "     ", uniqueWords[r], "     ", counts[r], "      ", (r + 1) * counts[r]);
        }
    }
    ret;
}

// A pangram uses every letter of the alphabet at least once. Finding the
// SMALLEST set of words (from some list) that together form a pangram is
// mathematically identical to Minimum Set Cover over a 26-element universe
// -- NP-hard in general. Here, brute force over all 2^8 subsets of the
// classic sentence's words is trivial, but it reveals something neat: this
// particular sentence has zero slack.

@pure
fn wordMask(word: Text) -> Int {
    let mask: Int = 0;
    loop i in 0..length(word) {
        let c: Int = ord(word[i..i + 1]);
        mask = mask | (1 << (c - 97));
    }
    ret mask;
}

@pure
fn popcount(x: Int) -> Int {
    let value: Int = x;
    let count: Int = 0;
    loop value != 0 { count = count + (value & 1); value = value >> 1; }
    ret count;
}

fn main() -> Void {
    let words: Text[] = ["the", "quick", "brown", "fox", "jumps", "over", "lazy", "dog"];
    let n: Int = length(words);
    let masks: Int[] = [];
    loop i in 0..n { masks = masks + [wordMask(words[i])]; }

    let fullMask: Int = (1 << 26) - 1;
    let bestCount: Int = n + 1;
    let bestSubset: Int = 0;

    let subset: Int = 0;
    loop subset < (1 << n) {
        let combined: Int = 0;
        let bit: Int = 0;
        loop bit < n {
            if (subset & (1 << bit)) != 0 { combined = combined | masks[bit]; }
            bit = bit + 1;
        }
        if combined == fullMask {
            let c: Int = popcount(subset);
            if c < bestCount { bestCount = c; bestSubset = subset; }
        }
        subset = subset + 1;
    }

    fx {
        println("Minimum pangram-covering subset of {the, quick, brown, fox, jumps, over, lazy, dog}:");
        let bit2: Int = 0;
        loop bit2 < n {
            if (bestSubset & (1 << bit2)) != 0 { print(words[bit2], " "); }
            bit2 = bit2 + 1;
        }
        println("");
        println("Words used: ", bestCount, " out of ", n);
    }
    ret;
}

// I Ching Hexagrams (Fuxi binary order)
// Each of the 64 hexagrams is a stack of six pictographic lines read
// from bottom to top. In Fuxi's arrangement, hexagram 0 is all broken
// (yin) lines, hexagram 63 is all solid (yang) lines, and the ordering
// is exactly binary counting -- making this the oldest known binary
// number representation, predating Leibniz by almost five millennia.

@pure
fn hexagramLines(value: Int) -> Text[] {
    let lines: Text[] = [];
    let v: Int = value;
    let i: Int = 0;
    loop i < 6 {
        if (v & 1) != 0 {
            lines = lines + ["━━━"];      // yang, unbroken line
        } else {
            lines = lines + ["━ ━"];      // yin, broken line
        }
        v = v >> 1;
        i = i + 1;
    }
    ret lines;
}

fn displayHexagram(value: Int) -> Void {
    let lines: Text[] = hexagramLines(value);
    fx {
        print("Hexagram ", value);
        if value < 10 {
            print("  ");
        } else {
            print(" ");
        }
        print("(");
        let j: Int = 5;
        loop j >= 0 {
            if ((value >> j) & 1) != 0 {
                print("1");
            } else {
                print("0");
            }
            j = j - 1;
        }
        println("):");
        let k: Int = 5;
        loop k >= 0 { println("    ", lines[k]); k = k - 1; }
        println("");
    }
    ret;
}

fn main() -> Void {
    fx {
        println("I Ching hexagrams in Fuxi binary order:");
        println("(bottom line = least significant bit)");
        println("");
    }
    loop h in 0..8 { displayHexagram(h); }
    fx { println("..."); }
    loop h in 60..64 { displayHexagram(h); }
    fx {
        println("All 64 hexagrams form a complete 6-bit binary system.");
        println("Fuxi order == binary 0-63. Leibniz 1703, after seeing");
        println("the diagrams, wrote 'Explication de l'Arithmetique");
        println("Binaire' citing the I Ching as independent discovery.");
    }
    ret;
}

// Hangul syllable composition: Unicode encodes pre-composed syllables
// at U+AC00-U+D7AF via a formula rather than individual assignment.
// A syllable = BASE + choseong_idx*588 + jungseong_idx*28 + jongseong_idx.
// chr(codepoint) renders the composed glyph directly -- the Unicode
// formula really is the whole composition algorithm.

@pure
fn findChoseongIdx(c: Text) -> Int {
    if c == "ㅎ" { ret 18; }
    if c == "ㄱ" { ret 0; }
    if c == "ㅅ" { ret 9; }
    if c == "ㅁ" { ret 6; }
    if c == "ㄷ" { ret 3; }
    if c == "ㅂ" { ret 7; }
    if c == "ㅈ" { ret 12; }
    if c == "ㅋ" { ret 15; }
    if c == "ㄴ" { ret 2; }
    ret -1;
}

@pure
fn findJungseongIdx(c: Text) -> Int {
    if c == "ㅏ" { ret 0; }
    if c == "ㅡ" { ret 18; }
    if c == "ㅜ" { ret 13; }
    if c == "ㅗ" { ret 8; }
    if c == "ㅓ" { ret 4; }
    if c == "ㅇ" { ret -99; } // not a vowel; guards against a bad call
    if c == "ㅣ" { ret 20; }
    ret -1;
}

@pure
fn findJongseongIdx(c: Text) -> Int {
    // 28-entry table: 0=none, 1=ㄱ..27=ㅎ, skipping the tensed stops
    // (ㄸ/ㅃ/ㅉ) which cannot occur as a syllable-final consonant.
    if c == "" { ret 0; }
    if c == "ㄱ" { ret 1; }
    if c == "ㄴ" { ret 4; }
    if c == "ㄹ" { ret 8; }
    if c == "ㅁ" { ret 16; }
    if c == "ㅂ" { ret 17; }
    if c == "ㅇ" { ret 21; }
    ret -1;
}

let SYLLABLE_BASE: Int = 44032;   // 0xAC00
let CHOSEONG_STEP: Int = 588;     // 21 jungseong * 28 jongseong
let JUNGSEONG_STEP: Int = 28;

@pure
fn composeHangul(choseong: Text, jungseong: Text, jongseong: Text) -> Int {
    let ci: Int = findChoseongIdx(choseong);
    let ji: Int = findJungseongIdx(jungseong);
    let ki: Int = findJongseongIdx(jongseong);
    if ci == -1 || ji == -1 || ki == -1 { ret 0; }
    ret SYLLABLE_BASE + ci * CHOSEONG_STEP + ji * JUNGSEONG_STEP + ki;
}

@pure
fn hexOfInt(n: Int) -> Text {
    let digits: Text = "0123456789ABCDEF";
    let v: Int = n;
    let out: Text = "";
    loop v > 0 {
        let d: Int = v % 16;
        out = digits[d..d + 1] + out;
        v = v / 16;
    }
    loop length(out) < 4 { out = "0" + out; }
    ret out;
}

fn main() -> Void {
    let choseongs: Text[] = ["ㅎ", "ㄱ", "ㅅ", "ㅁ", "ㄷ", "ㅂ", "ㅈ", "ㅋ", "ㄴ", "ㄱ"];
    let jungseongs: Text[] = ["ㅏ", "ㅡ", "ㅏ", "ㅜ", "ㅗ", "ㅓ", "ㅏ", "ㅣ", "ㅏ", "ㅜ"];
    let jongseongs: Text[] = ["ㄴ", "ㄹ", "ㄴ", "ㄴ", "", "ㅂ", "ㅇ", "ㅁ", "ㄹ", "ㄱ"];

    fx {
        println("Hangul syllable composition:");
        println("jamo      -> syllable (Unicode codepoint)");
        println("----------------------------------------");
    }
    loop s in 0..length(choseongs) {
        let cp: Int = composeHangul(choseongs[s], jungseongs[s], jongseongs[s]);
        let glyph: Text = chr(cp);
        fx {
            println(choseongs[s], jungseongs[s], jongseongs[s],
                    "  ->  U+", hexOfInt(cp), "  ", glyph);
        }
    }
    ret;
}

// Kangxi Radical Grouping: the 214 radicals classify every CJK
// character by its semantic root. Characters sharing a radical (e.g.
// 口 "mouth": 吃 eat, 喝 drink, 叫 call, 唱 sing) share meaning.
// This is a pure lookup-and-group problem, but the structure it reveals
// is the oldest surviving semantic classification system in the world.

type RadicalEntry {
    character: Text;
    radical: Text;
    radicalNum: Int;
}

type RadicalGroup {
    radical: Text;
    radicalNum: Int;
    meaning: Text;
    members: Text[];
}

@pure
fn lookupRadical(c: Text) -> RadicalEntry {
    // A small lookup covering the example characters in the sample.
    if c == "火" { ret RadicalEntry{character: c, radical: "火", radicalNum: 86}; }
    if c == "烧" { ret RadicalEntry{character: c, radical: "火", radicalNum: 86}; }
    if c == "灯" { ret RadicalEntry{character: c, radical: "火", radicalNum: 86}; }
    if c == "灾" { ret RadicalEntry{character: c, radical: "火", radicalNum: 86}; }
    if c == "吃" { ret RadicalEntry{character: c, radical: "口", radicalNum: 30}; }
    if c == "喝" { ret RadicalEntry{character: c, radical: "口", radicalNum: 30}; }
    if c == "叫" { ret RadicalEntry{character: c, radical: "口", radicalNum: 30}; }
    if c == "唱" { ret RadicalEntry{character: c, radical: "口", radicalNum: 30}; }
    if c == "水" { ret RadicalEntry{character: c, radical: "水", radicalNum: 85}; }
    if c == "江" { ret RadicalEntry{character: c, radical: "水", radicalNum: 85}; }
    if c == "河" { ret RadicalEntry{character: c, radical: "水", radicalNum: 85}; }
    if c == "海" { ret RadicalEntry{character: c, radical: "水", radicalNum: 85}; }
    if c == "木" { ret RadicalEntry{character: c, radical: "木", radicalNum: 75}; }
    if c == "林" { ret RadicalEntry{character: c, radical: "木", radicalNum: 75}; }
    if c == "森" { ret RadicalEntry{character: c, radical: "木", radicalNum: 75}; }
    if c == "桥" { ret RadicalEntry{character: c, radical: "木", radicalNum: 75}; }
    if c == "心" { ret RadicalEntry{character: c, radical: "心", radicalNum: 61}; }
    if c == "想" { ret RadicalEntry{character: c, radical: "心", radicalNum: 61}; }
    if c == "思" { ret RadicalEntry{character: c, radical: "心", radicalNum: 61}; }
    if c == "念" { ret RadicalEntry{character: c, radical: "心", radicalNum: 61}; }
    if c == "金" { ret RadicalEntry{character: c, radical: "金", radicalNum: 167}; }
    if c == "铁" { ret RadicalEntry{character: c, radical: "金", radicalNum: 167}; }
    if c == "铜" { ret RadicalEntry{character: c, radical: "金", radicalNum: 167}; }
    if c == "银" { ret RadicalEntry{character: c, radical: "金", radicalNum: 167}; }
    ret RadicalEntry{character: c, radical: "?", radicalNum: 0};
}

@pure
fn radicalMeaning(radical: Text) -> Text {
    if radical == "火" { ret "fire"; }
    if radical == "口" { ret "mouth"; }
    if radical == "水" { ret "water"; }
    if radical == "木" { ret "tree/wood"; }
    if radical == "心" { ret "heart/mind"; }
    if radical == "金" { ret "metal/gold"; }
    ret "unknown";
}

fn main() -> Void {
    let sample: Text[] = [
        "火", "烧", "灯", "灾",
        "吃", "喝", "叫", "唱",
        "水", "江", "河", "海",
        "木", "林", "森", "桥",
        "心", "想", "思", "念",
        "金", "铁", "铜", "银"
    ];

    let groups: RadicalGroup[] = [];

    loop i in 0..length(sample) {
        let entry: RadicalEntry = lookupRadical(sample[i]);
        let foundGroup: Bool = false;
        loop g in 0..length(groups) {
            if groups[g].radical == entry.radical {
                groups[g].members = groups[g].members + [entry.character];
                foundGroup = true;
                break;
            }
        }
        if !foundGroup {
            groups = groups + [RadicalGroup{
                radical: entry.radical,
                radicalNum: entry.radicalNum,
                meaning: radicalMeaning(entry.radical),
                members: [entry.character]
            }];
        }
    }

    fx { println("Kangxi radical groupings:"); println(""); }
    loop g in 0..length(groups) {
        fx {
            println("Radical ", groups[g].radicalNum, " ", groups[g].radical,
                    "  (", groups[g].meaning, "):");
        }
        let first: Bool = true;
        loop m in 0..length(groups[g].members) {
            fx {
                if !first { print(", "); }
                print(groups[g].members[m]);
                first = false;
            }
        }
        fx { println(""); println(""); }
    }
    ret;
}

// Braille: a tactile pictograph system where each character is a 2x3
// matrix of raised dots. In Unicode, every possible on/off pattern of
// the six dots is a distinct pictograph at U+2800 + pattern. The dot
// numbering is:
//   1 4
//   2 5
//   3 6
// Letters a-z map to standard Braille patterns (decimal here -- Aether
// has no `0b` binary literal syntax). chr(0x2800 + pattern) renders the
// glyph directly.

@pure
fn braillePattern(letter: Text) -> Int {
    if letter == "a" { ret 1; }    // dot 1
    if letter == "b" { ret 3; }    // dots 1+2
    if letter == "c" { ret 9; }    // dots 1+4
    if letter == "d" { ret 25; }   // dots 1+4+5
    if letter == "e" { ret 17; }   // dots 1+5
    if letter == "f" { ret 11; }   // dots 1+2+4
    if letter == "g" { ret 27; }   // dots 1+2+4+5
    if letter == "h" { ret 19; }   // dots 1+2+5
    if letter == "i" { ret 10; }   // dots 2+4
    if letter == "j" { ret 26; }   // dots 2+4+5
    if letter == "k" { ret 5; }    // dots 1+3
    if letter == "l" { ret 7; }    // dots 1+2+3
    if letter == "m" { ret 13; }   // dots 1+3+4
    if letter == "n" { ret 29; }   // dots 1+3+4+5
    if letter == "o" { ret 21; }   // dots 1+3+5
    if letter == "p" { ret 15; }   // dots 1+2+3+4
    if letter == "q" { ret 31; }   // dots 1+2+3+4+5
    if letter == "r" { ret 23; }   // dots 1+2+3+5
    if letter == "s" { ret 14; }   // dots 2+3+4
    if letter == "t" { ret 30; }   // dots 2+3+4+5
    if letter == "u" { ret 37; }   // dots 1+3+6
    if letter == "v" { ret 39; }   // dots 1+2+3+6
    if letter == "w" { ret 58; }   // dots 2+4+5+6 (w is special in Braille)
    if letter == "x" { ret 45; }   // dots 1+3+4+6
    if letter == "y" { ret 61; }   // dots 1+3+4+5+6
    if letter == "z" { ret 53; }   // dots 1+3+5+6
    ret 0;                          // space or unknown
}

@pure
fn letterFromPattern(pattern: Int) -> Text {
    if pattern == 1 { ret "a"; }
    if pattern == 3 { ret "b"; }
    if pattern == 9 { ret "c"; }
    if pattern == 25 { ret "d"; }
    if pattern == 17 { ret "e"; }
    if pattern == 11 { ret "f"; }
    if pattern == 27 { ret "g"; }
    if pattern == 19 { ret "h"; }
    if pattern == 10 { ret "i"; }
    if pattern == 26 { ret "j"; }
    if pattern == 5 { ret "k"; }
    if pattern == 7 { ret "l"; }
    if pattern == 13 { ret "m"; }
    if pattern == 29 { ret "n"; }
    if pattern == 21 { ret "o"; }
    if pattern == 15 { ret "p"; }
    if pattern == 31 { ret "q"; }
    if pattern == 23 { ret "r"; }
    if pattern == 14 { ret "s"; }
    if pattern == 30 { ret "t"; }
    if pattern == 37 { ret "u"; }
    if pattern == 39 { ret "v"; }
    if pattern == 58 { ret "w"; }
    if pattern == 45 { ret "x"; }
    if pattern == 61 { ret "y"; }
    if pattern == 53 { ret "z"; }
    if pattern == 0 { ret " "; }
    ret "?";
}

@pure
fn brailleChar(letter: Text) -> Text {
    ret chr(0x2800 + braillePattern(letter));
}

@pure
fn hexOfInt(n: Int) -> Text {
    let digits: Text = "0123456789ABCDEF";
    let v: Int = n;
    let out: Text = "";
    if v == 0 { ret "00"; }
    loop v > 0 {
        let d: Int = v % 16;
        out = digits[d..d + 1] + out;
        v = v / 16;
    }
    loop length(out) < 2 { out = "0" + out; }
    ret out;
}

fn main() -> Void {
    let message: Text = "aether pictograph";

    fx {
        println("Text to Braille pictograph encoding:");
        println("");
        print("Plain:     ");
        loop i in 0..length(message) { print(message[i..i + 1], " "); }
        println("");

        print("Braille:   ");
        loop i in 0..length(message) {
            let c: Text = message[i..i + 1];
            print(brailleChar(c), " ");
        }
        println("");

        print("Patterns:  ");
        loop i in 0..length(message) {
            let c: Text = message[i..i + 1];
            let pat: Int = braillePattern(c);
            print(hexOfInt(pat), " ");
        }
        println("");
        println("");

        println("Decoding back:");
    }
    let decoded: Text = "";
    loop i in 0..length(message) {
        let c: Text = message[i..i + 1];
        let pat: Int = braillePattern(c);
        decoded = decoded + letterFromPattern(pat);
    }
    fx { println("Decoded: ", decoded); }
    ret;
}

// Roman numerals: seven pictographs whose shapes originate from
// hand gestures and tally marks.
//   I = one finger       V = hand shape (four fingers+thumb)
//   X = crossed hands    L = half of C
//   C = centum (100)     D = half of M
//   M = mille (1000)
// The subtractive rule (IV not IIII) evolved in the Republic era;
// earlier Romans wrote IIII for 4. This modern form is bidirectional.

@pure
fn toRoman(n: Int) -> Text {
    let values: Int[] = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
    let symbols: Text[] = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
    let result: Text = "";
    let remaining: Int = n;
    loop i in 0..length(values) {
        loop remaining >= values[i] {
            result = result + symbols[i];
            remaining = remaining - values[i];
        }
    }
    ret result;
}

@pure
fn romanValue(c: Text) -> Int {
    if c == "I" { ret 1; }
    if c == "V" { ret 5; }
    if c == "X" { ret 10; }
    if c == "L" { ret 50; }
    if c == "C" { ret 100; }
    if c == "D" { ret 500; }
    if c == "M" { ret 1000; }
    ret 0;
}

@pre length(s) > 0
@pure
fn fromRoman(s: Text) -> Int {
    let total: Int = 0;
    let i: Int = 0;
    loop i < length(s) {
        let cur: Int = romanValue(s[i..i + 1]);
        if i + 1 < length(s) {
            let next: Int = romanValue(s[i + 1..i + 1 + 1]);
            if cur < next {
                total = total + (next - cur);
                i = i + 2;
            } else {
                total = total + cur;
                i = i + 1;
            }
        } else {
            total = total + cur;
            i = i + 1;
        }
    }
    ret total;
}

@pure
fn padLeft(s: Text, width: Int) -> Text {
    let out: Text = s;
    loop length(out) < width { out = " " + out; }
    ret out;
}

@pure
fn padRight(s: Text, width: Int) -> Text {
    let out: Text = s;
    loop length(out) < width { out = out + " "; }
    ret out;
}

fn main() -> Void {
    let testNumbers: Int[] = [1, 4, 9, 14, 19, 49, 99, 499, 999, 1499, 2026, 3999];

    fx {
        println("Decimal -> Roman -> Decimal (round-trip verification):");
        println(" dec   roman          back   match");
        println("----------------------------------------");
    }
    loop i in 0..length(testNumbers) {
        let n: Int = testNumbers[i];
        let rom: Text = toRoman(n);
        let back: Int = fromRoman(rom);
        let ok: Text = "OK";
        if back != n { ok = "MISMATCH"; }
        fx {
            println(padLeft(int_to_text(n), 4), "  ", padRight(rom, 10), "  ", padLeft(int_to_text(back), 6), "  ", ok);
        }
    }
    ret;
}

// Baconian Biliteral Cipher (Francis Bacon, De Augmentis Scientiarum, 1623)
// Each letter A-Z is encoded as a 5-bit pattern of 'a'/'b' -- the first known
// binary encoding of a Latin alphabet, predating Morse code by over 200 years.

@pure
fn baconPattern(c: Text) -> Text {
    let code: Int = ord(c);
    if code < 65 || code > 90 { ret "?????"; }
    let idx: Int = code - 65;
    let pattern: Text = "";
    let bit: Int = 4;
    loop bit >= 0 {
        if (idx >> bit) & 1 != 0 {
            pattern = pattern + "b";
        } else {
            pattern = pattern + "a";
        }
        bit = bit - 1;
    }
    ret pattern;
}

@pure
fn fromBaconPattern(pattern: Text) -> Text {
    let val: Int = 0;
    let i: Int = 0;
    loop i < 5 {
        val = val << 1;
        if pattern[i..i + 1] == "b" { val = val | 1; }
        i = i + 1;
    }
    if val < 0 || val > 25 { ret "?"; }
    ret chr(val + 65);
}

@pure
fn encodeMessage(message: Text) -> Text {
    let result: Text = "";
    let len: Int = string_len(message);
    let i: Int = 0;
    loop i < len {
        let ch: Text = message[i..i + 1];
        let code: Int = ord(ch);
        if code >= 97 && code <= 122 { ch = chr(code - 32); }
        if i > 0 { result = result + " "; }
        result = result + baconPattern(ch);
        i = i + 1;
    }
    ret result;
}

@pure
fn decodeMessage(patterns: Text) -> Text {
    let result: Text = "";
    let len: Int = string_len(patterns);
    let start: Int = 0;
    let i: Int = 0;
    loop i <= len {
        let atEnd: Bool = i == len;
        let isSpace: Bool = false;
        if !atEnd { isSpace = patterns[i..i + 1] == " "; }
        if atEnd || isSpace {
            if i > start {
                result = result + fromBaconPattern(patterns[start..start + i - start]);
            }
            start = i + 1;
        }
        i = i + 1;
    }
    ret result;
}

fn main() -> Void {
    let message: Text = "BACON";
    let encoded: Text = encodeMessage(message);
    let decoded: Text = decodeMessage(encoded);

    fx {
        println("Baconian Biliteral Cipher (1605):");
        println("Plaintext:  ", message);
        println("Bacon bits: ", encoded);
        println("Decoded:    ", decoded);
        println("");
        println("Full alphabet mapping:");
    }

    let letter: Int = 65;
    loop letter <= 90 {
        let c: Text = chr(letter);
        let p: Text = baconPattern(c);
        let back: Text = fromBaconPattern(p);
        fx { println("  ", c, " -> ", p); }
        if back != c { fx { println("ROUNDTRIP FAIL at ", c); } }
        letter = letter + 1;
    }
    fx { println("Roundtrip verified for all 26 letters."); }
    ret;
}

// Caesar Cipher - shifts each letter by a fixed number
fn shiftChar(ch: Text, shift: Int) -> Text {
    let code: Int = ord(ch);
    if code >= ord("A") && code <= ord("Z") {
        ret chr(((code - ord("A") + shift) % 26) + ord("A"));
    }
    if code >= ord("a") && code <= ord("z") {
        ret chr(((code - ord("a") + shift) % 26) + ord("a"));
    }
    ret ch;
}

fn caesarEncrypt(text: Text, shift: Int) -> Text {
    let result: Text = "";
    loop i in 0..string_len(text) {
        let ch: Text = text[i..i + 1];
        result = result + shiftChar(ch, shift);
    }
    ret result;
}

fn caesarDecrypt(text: Text, shift: Int) -> Text {
    ret caesarEncrypt(text, 26 - (shift % 26));
}

fn main() -> Void {
    fx {
        let message: Text = "Hello World";
        let shift: Int = 3;
        let encrypted: Text = caesarEncrypt(message, shift);
        let decrypted: Text = caesarDecrypt(encrypted, shift);
        println("Original: ", message);
        println("Encrypted: ", encrypted);
        println("Decrypted: ", decrypted);
    }
    ret;
}

// Vigenère Cipher - uses a keyword to shift letters
fn vigenereEncrypt(text: Text, key: Text) -> Text {
    let result: Text = "";
    let keyLen: Int = string_len(key);
    let keyIndex: Int = 0;
    loop i in 0..string_len(text) {
        let ch: Text = text[i..i + 1];
        let code: Int = ord(ch);
        if (code >= ord("A") && code <= ord("Z")) || (code >= ord("a") && code <= ord("z")) {
            let keyChar: Text = key[(keyIndex % keyLen)..(keyIndex % keyLen) + 1];
            let shift: Int = ord(keyChar) - ord("a");
            if code >= ord("A") && code <= ord("Z") {
                result = result + chr(((code - ord("A") + shift) % 26) + ord("A"));
            } else {
                result = result + chr(((code - ord("a") + shift) % 26) + ord("a"));
            }
            keyIndex = keyIndex + 1;
        } else {
            result = result + ch;
        }
    }
    ret result;
}

fn vigenereDecrypt(text: Text, key: Text) -> Text {
    let result: Text = "";
    let keyLen: Int = string_len(key);
    let keyIndex: Int = 0;
    loop i in 0..string_len(text) {
        let ch: Text = text[i..i + 1];
        let code: Int = ord(ch);
        if (code >= ord("A") && code <= ord("Z")) || (code >= ord("a") && code <= ord("z")) {
            let keyChar: Text = key[(keyIndex % keyLen)..(keyIndex % keyLen) + 1];
            let shift: Int = ord(keyChar) - ord("a");
            if code >= ord("A") && code <= ord("Z") {
                result = result + chr(((code - ord("A") - shift + 26) % 26) + ord("A"));
            } else {
                result = result + chr(((code - ord("a") - shift + 26) % 26) + ord("a"));
            }
            keyIndex = keyIndex + 1;
        } else {
            result = result + ch;
        }
    }
    ret result;
}

fn main() -> Void {
    fx {
        let message: Text = "Attack at dawn";
        let key: Text = "lemon";
        let encrypted: Text = vigenereEncrypt(message, key);
        let decrypted: Text = vigenereDecrypt(encrypted, key);
        println("Original: ", message);
        println("Encrypted: ", encrypted);
        println("Decrypted: ", decrypted);
    }
    ret;
}

// Substitution Cipher - replaces each letter with a fixed permutation
fn substitutionEncrypt(text: Text, mapping: Text) -> Text {
    let result: Text = "";
    loop i in 0..string_len(text) {
        let ch: Text = text[i..i + 1];
        let code: Int = ord(ch);
        if code >= ord("A") && code <= ord("Z") {
            let index: Int = code - ord("A");
            let mappedChar: Text = mapping[index..index + 1];
            result = result + mappedChar;
        } else if code >= ord("a") && code <= ord("z") {
            let index: Int = code - ord("a");
            let mappedChar: Text = mapping[index..index + 1];
            // mapping is all-uppercase; downcase the substituted letter so
            // encryption preserves the original letter's case for decrypt.
            result = result + chr(ord(mappedChar) + 32);
        } else {
            result = result + ch;
        }
    }
    ret result;
}

fn substitutionDecrypt(text: Text, mapping: Text) -> Text {
    let result: Text = "";
    loop i in 0..string_len(text) {
        let ch: Text = text[i..i + 1];
        let code: Int = ord(ch);
        if code >= ord("A") && code <= ord("Z") {
            let index: Int = index_of(mapping, ch);
            if index >= 0 {
                result = result + chr(index + ord("A"));
            } else {
                result = result + ch;
            }
        } else if code >= ord("a") && code <= ord("z") {
            let upperCh: Text = repeat(chr(code - 32), 1);
            let index: Int = index_of(mapping, upperCh);
            if index >= 0 {
                result = result + chr(index + ord("a"));
            } else {
                result = result + ch;
            }
        } else {
            result = result + ch;
        }
    }
    ret result;
}

fn main() -> Void {
    fx {
        let message: Text = "Hello World";
        let mapping: Text = "QWERTYUIOPASDFGHJKLZXCVBNM";
        let encrypted: Text = substitutionEncrypt(message, mapping);
        let decrypted: Text = substitutionDecrypt(encrypted, mapping);
        println("Original: ", message);
        println("Encrypted: ", encrypted);
        println("Decrypted: ", decrypted);
    }
    ret;
}

// Rail Fence Cipher - writes text in a zigzag pattern and reads off rows
fn railFenceEncrypt(text: Text, rails: Int) -> Text {
    if rails <= 1 || string_len(text) <= 1 { ret text; }
    let fence: Text[] = [];
    loop i in 0..rails { fence = fence + [""]; }
    let currentRail: Int = 0;
    let direction: Int = 1;
    loop i in 0..string_len(text) {
        let ch: Text = text[i..i + 1];
        fence[currentRail] = fence[currentRail] + ch;
        if currentRail == 0 {
            direction = 1;
        } else if currentRail == rails - 1 {
            direction = -1;
        }
        currentRail = currentRail + direction;
    }
    let result: Text = "";
    loop i in 0..rails { result = result + fence[i]; }
    ret result;
}

fn railFenceDecrypt(text: Text, rails: Int) -> Text {
    if rails <= 1 || string_len(text) <= 1 { ret text; }
    let n: Int = string_len(text);
    let railLengths: Int[] = [];
    loop i in 0..rails { railLengths = railLengths + [0]; }
    let currentRail: Int = 0;
    let direction: Int = 1;
    loop i in 0..n {
        railLengths[currentRail] = railLengths[currentRail] + 1;
        if currentRail == 0 {
            direction = 1;
        } else if currentRail == rails - 1 {
            direction = -1;
        }
        currentRail = currentRail + direction;
    }
    let railData: Text[] = [];
    let index: Int = 0;
    loop i in 0..rails {
        railData = railData + [text[index..index + railLengths[i]]];
        index = index + railLengths[i];
    }
    let railIndices: Int[] = [];
    loop i in 0..rails { railIndices = railIndices + [0]; }
    let result: Text = "";
    currentRail = 0;
    direction = 1;
    loop i in 0..n {
        let railText: Text = railData[currentRail];
        let pos: Int = railIndices[currentRail];
        result = result + railText[pos..pos + 1];
        railIndices[currentRail] = railIndices[currentRail] + 1;
        if currentRail == 0 {
            direction = 1;
        } else if currentRail == rails - 1 {
            direction = -1;
        }
        currentRail = currentRail + direction;
    }
    ret result;
}

fn main() -> Void {
    fx {
        let message: Text = "HELLO WORLD";
        let rails: Int = 3;
        let encrypted: Text = railFenceEncrypt(message, rails);
        let decrypted: Text = railFenceDecrypt(encrypted, rails);
        println("Original: ", message);
        println("Encrypted: ", encrypted);
        println("Decrypted: ", decrypted);
    }
    ret;
}

// XOR Cipher - applies bitwise XOR with a repeating key
fn xorCipher(text: Text, key: Text) -> Text {
    let result: Text = "";
    let keyLen: Int = string_len(key);
    loop i in 0..string_len(text) {
        let ch: Text = text[i..i + 1];
        let keyChar: Text = key[(i % keyLen)..(i % keyLen) + 1];
        let xorResult: Int = ord(ch) xor ord(keyChar);
        result = result + chr(xorResult);
    }
    ret result;
}

fn main() -> Void {
    fx {
        let message: Text = "Secret Message";
        let key: Text = "KEY";
        let encrypted: Text = xorCipher(message, key);
        let decrypted: Text = xorCipher(encrypted, key);
        println("Original: ", message);
        println("Encrypted (first byte, decimal): ", int_to_text(ord(encrypted[..1])));
        println("Decrypted: ", decrypted);
    }
    ret;
}

// Mayan Long Count to Julian Day conversion
fn longCountToJD(baktun: Int, katun: Int, tun: Int, winal: Int, kin: Int) -> Int {
    const GMT_CONSTANT: Int = 584283;
    let totalDays: Int = baktun * 144000 + katun * 7200 + tun * 360 + winal * 20 + kin;
    ret GMT_CONSTANT + totalDays;
}

fn jdToLongCount(jd: Int) -> (Int, Int, Int, Int, Int) {
    const GMT_CONSTANT: Int = 584283;
    let totalDays: Int = jd - GMT_CONSTANT;

    let baktun: Int = totalDays / 144000;
    totalDays = totalDays % 144000;

    let katun: Int = totalDays / 7200;
    totalDays = totalDays % 7200;

    let tun: Int = totalDays / 360;
    totalDays = totalDays % 360;

    let winal: Int = totalDays / 20;
    let kin: Int = totalDays % 20;

    ret (baktun, katun, tun, winal, kin);
}

// Tzolk'in: 260-day cycle (13 numbers x 20 day names)
fn tzolkinFromJD(jd: Int) -> (Int, Text) {
    // NOTE: day names stored as a Text[] array, not a fixed-width packed
    // string -- the names have unequal length (Imix=4, Ik=2, Akbal=5, ...),
    // so a fixed-stride copy() slice misaligns and returns garbage.
    let dayNames: Text[] = ["Imix","Ik","Akbal","Kan","Chicchan","Cimi","Manik",
                             "Lamat","Muluc","Oc","Chuen","Eb","Ben","Ix","Men",
                             "Cib","Caban","Etznab","Cauac","Ahau"];
    let dayNumber: Int = ((jd - 2) % 13) + 1;
    let dayIndex: Int = (jd - 2) % 20;
    ret (dayNumber, dayNames[dayIndex]);
}

// Haab': 365-day cycle (18 months x 20 days + 5 Wayeb')
fn haabFromJD(jd: Int) -> (Int, Text) {
    // Same fixed-width-vs-unequal-length pitfall as tzolkinFromJD -- use an
    // array instead of a packed string.
    let monthNames: Text[] = ["Pop","Uo","Zip","Zotz","Tzec","Xul","Yaxkin",
                               "Mol","Chen","Yax","Zac","Ceh","Mac","Kankin",
                               "Muan","Pax","Kayab","Cumku","Wayeb"];
    let dayOfHaab: Int = (jd - 584283) % 365;
    if dayOfHaab < 0 { dayOfHaab = dayOfHaab + 365; }

    let monthIndex: Int = dayOfHaab / 20;
    let dayInMonth: Int = dayOfHaab % 20;

    if monthIndex >= 18 { monthIndex = 18; }

    ret (dayInMonth, monthNames[monthIndex]);
}

fn main() -> Void {
    fx {
        // Example: Long Count 13.0.0.0.0 (creation date)
        let jd: Int = longCountToJD(13, 0, 0, 0, 0);
        println("Long Count 13.0.0.0.0 -> JD: ", jd);

        // Convert back
        let (b, k, t, w, ki) = jdToLongCount(jd);
        println("JD ", jd, " -> Long Count: ", b, ".", k, ".", t, ".", w, ".", ki);

        // Tzolk'in and Haab' for this date
        let (tzNumber, tzName) = tzolkinFromJD(jd);
        let (hDay, hMonth) = haabFromJD(jd);
        println("Tzolk'in: ", tzNumber, " ", tzName);
        println("Haab': ", hDay, " ", hMonth);
    }
    ret;
}

// Chinese calendar with leap month detection
fn isLeapYear(year: Int) -> Bool {
    ret (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// Approximate winter solstice date (Dec 21/22)
fn winterSolstice(year: Int) -> Int {
    // Simplified: returns day of year (355 or 356)
    if isLeapYear(year) {
        ret 356; // Dec 21 in leap year
    } else {
        ret 355; // Dec 21 in common year
    }
}

// Metonic cycle: 7 leap months in 19 years
fn isChineseLeapMonth(year: Int, month: Int) -> Bool {
    // Years 3, 6, 8, 11, 14, 17, 19 in 19-year cycle have leap months
    let cycleYear: Int = (year - 1) % 19 + 1;
    if cycleYear == 3 || cycleYear == 6 || cycleYear == 8 || cycleYear == 11 ||
       cycleYear == 14 || cycleYear == 17 || cycleYear == 19 {
        ret true;
    }
    ret false;
}

// Determine which month is leap (simplified)
fn getLeapMonth(year: Int) -> Int {
    let cycleYear: Int = (year - 1) % 19 + 1;
    if cycleYear == 3 { ret 3; }
    if cycleYear == 6 { ret 6; }
    if cycleYear == 8 { ret 8; }
    if cycleYear == 11 { ret 11; }
    if cycleYear == 14 { ret 14; }
    if cycleYear == 17 { ret 17; }
    if cycleYear == 19 { ret 19; }
    ret 0; // No leap month
}

// Convert Chinese year/month to approximate Gregorian
fn chineseToGregorian(year: Int, month: Int, isLeap: Bool) -> (Int, Int) {
    // Base year 1900 for calculation
    const baseYear: Int = 1900;
    let yearOffset: Int = year - baseYear;

    // Approximate months from winter solstice
    let monthOffset: Int = month - 11; // 11th month contains winter solstice

    if isLeap { monthOffset = monthOffset + 1; }

    // Very rough conversion (not accounting for exact lunar months)
    let gregorianMonth: Int = ((monthOffset + 11) % 12) + 1;
    let gregorianYear: Int = baseYear + yearOffset + (monthOffset + 11) / 12;

    ret (gregorianYear, gregorianMonth);
}

fn main() -> Void {
    fx {
        let testYear: Int = 2025;
        let leapMonth: Int = getLeapMonth(testYear);

        println("Year ", testYear, " has leap month: ", leapMonth);

        // Test conversion for a leap month
        if leapMonth > 0 {
            let (gy, gm) = chineseToGregorian(testYear, leapMonth, true);
            println("Leap month ", leapMonth, " in year ", testYear,
                    " approximates to ", gm, "/", gy);
        }

        // Check Metonic cycle position
        let cyclePos: Int = (testYear - 1) % 19 + 1;
        println("Year ", testYear, " is position ", cyclePos, " in Metonic cycle");
    }
    ret;
}

// Byzantine calendar calculations
fn byzantineAM(year: Int, month: Int) -> Int {
    // Epoch: 1 Sep 5509 BCE
    // Year offset: +5508 for Jan-Aug, +5509 for Sep-Dec
    if month >= 9 {
        ret year + 5509;
    } else {
        ret year + 5508;
    }
}

fn indiction(year: Int) -> Int {
    // 15-year tax cycle starting 312 CE
    // Year 313 CE = indiction 1
    let offset: Int = year - 312;
    ret (offset % 15) + 1;
}

fn verifyByzantineDate(year: Int, month: Int, amYear: Int, indictionYear: Int) -> Bool {
    let calculatedAM: Int = byzantineAM(year, month);
    let calculatedIndiction: Int = indiction(year);

    ret calculatedAM == amYear && calculatedIndiction == indictionYear;
}

fn byzantineToDate(amYear: Int, indictionYear: Int) -> (Int, Int) {
    // Find year where AM and indiction match
    // AM year = year + 5508 or 5509
    // Indiction = (year - 312) % 15 + 1

    loop testYear in 1..10000 {
        let am1: Int = testYear + 5508;
        let am2: Int = testYear + 5509;
        let ind: Int = indiction(testYear);

        if (am1 == amYear || am2 == amYear) && ind == indictionYear {
            ret (testYear, 0); // 0 means we can't determine month from this alone
        }
    }
    ret (-1, -1); // Not found
}

fn main() -> Void {
    fx {
        // Test year 2024
        let year: Int = 2024;
        let am: Int = byzantineAM(year, 6); // June
        let ind: Int = indiction(year);

        println("Year ", year, " (June) -> AM: ", am, ", Indiction: ", ind);

        // Verify consistency
        let valid: Bool = verifyByzantineDate(year, 6, am, ind);
        println("Date verification: ", valid);

        // Reverse lookup
        let (foundYear, foundMonth) = byzantineToDate(am, ind);
        println("AM ", am, " + Indiction ", ind, " -> Year: ", foundYear);
    }
    ret;
}

// French Republican Calendar
fn isRepublicanLeap(year: Int) -> Bool {
    // Romme's rule: years 3, 7, 11 are leap (year 1 is not)
    let cycleYear: Int = (year - 1) % 4 + 1;
    ret cycleYear == 3 || cycleYear == 7 || cycleYear == 11;
}

fn dayOfYearToRepublican(dayOfYear: Int, year: Int) -> (Int, Int) {
    // Returns (month, dayInMonth)
    // 12 months x 30 days = 360, plus 5-6 sans-culottides

    if dayOfYear <= 360 {
        let month: Int = (dayOfYear - 1) / 30 + 1;
        let day: Int = (dayOfYear - 1) % 30 + 1;
        ret (month, day);
    } else {
        // Sans-culottides (5 or 6 days)
        let extraDay: Int = dayOfYear - 360;
        ret (13, extraDay); // Month 13 = sans-culottides
    }
}

fn republicanMonthName(month: Int) -> Text {
    // NOTE: month names as a Text[] array, not a fixed-width packed string --
    // the names have unequal length (Nivôse=6, Thermidor=9, ...), so a
    // fixed-stride copy() slice misaligns and returns garbage.
    let monthNames: Text[] = ["Vendémiaire","Brumaire","Frimaire","Nivôse",
                               "Pluviôse","Ventôse","Germinal","Floréal",
                               "Prairial","Messidor","Thermidor","Fructidor",
                               "Sans-culottides"];
    if month >= 1 && month <= 13 { ret monthNames[month - 1]; }
    ret "Invalid";
}

fn republicanDayName(day: Int) -> Text {
    // Décade: 10-day weeks. Same fixed-width pitfall as above -- use an array.
    let dayNames: Text[] = ["Primidi","Duodi","Tridi","Quartidi","Quintidi",
                             "Sextidi","Septidi","Octidi","Nonidi","Décadi"];
    if day >= 1 && day <= 10 { ret dayNames[day - 1]; }
    ret "Invalid";
}

fn gregorianToRepublican(year: Int, month: Int, day: Int) -> (Int, Int, Int) {
    // Simplified conversion starting from 22 Sep 1792 (Republican Year 1)
    const baseYear: Int = 1792;
    const baseMonth: Int = 9;
    const baseDay: Int = 22;

    // Calculate days since Republican epoch
    let daysSinceEpoch: Int = 0;
    let currentYear: Int = baseYear;
    let currentMonth: Int = baseMonth;
    let currentDay: Int = baseDay;

    // Very simplified - just counting years
    let republicanYear: Int = year - baseYear + 1;

    // Approximate day of year
    let dayOfYear: Int = day;
    if month > 1 { dayOfYear = dayOfYear + 31; }
    if month > 2 { dayOfYear = dayOfYear + 28; if (year % 4 == 0) { dayOfYear = dayOfYear + 1; } }
    if month > 3 { dayOfYear = dayOfYear + 31; }
    if month > 4 { dayOfYear = dayOfYear + 30; }
    if month > 5 { dayOfYear = dayOfYear + 31; }
    if month > 6 { dayOfYear = dayOfYear + 30; }
    if month > 7 { dayOfYear = dayOfYear + 31; }
    if month > 8 { dayOfYear = dayOfYear + 31; }
    if month > 9 { dayOfYear = dayOfYear + 30; }
    if month > 10 { dayOfYear = dayOfYear + 31; }
    if month > 11 { dayOfYear = dayOfYear + 30; }

    let (repMonth, repDay) = dayOfYearToRepublican(dayOfYear, republicanYear);
    ret (republicanYear, repMonth, repDay);
}

fn main() -> Void {
    fx {
        // Test date: 1 Jan 2024
        let (year, month, day) = gregorianToRepublican(2024, 1, 1);
        let monthName: Text = republicanMonthName(month);
        let dayName: Text = republicanDayName(day);

        println("1 Jan 2024 -> Republican Year ", year, ", ", monthName, " ", day, " (", dayName, ")");

